// Document insights: counts, reading time, readability and vocabulary.

import { splitSentences, tokenizeWords, syllableCount, isCheckable } from './text.js';
import { CATEGORIES } from './issues.js';

var DEVANAGARI_WORD = /[\u0900-\u097f]+/g;

var STOPWORDS = toSet((
  'a about above after again against all also am an and any are as at be because been before being below between ' +
  'both but by can could did do does doing down during each few for from further had has have having he her here ' +
  'hers herself him himself his how i if in into is it its itself just me more most my myself no nor not now of off ' +
  'on once only or other our ours ourselves out over own same she should so some such than that the their theirs ' +
  'them themselves then there these they this those through to too under until up very was we were what when where ' +
  'which while who whom why will with would you your yours yourself yourselves shall may might must per via etc ' +
  'one two three four five six seven eight nine ten also however therefore thus hence within without upon whether ' +
  'been being used use using based new well'
).split(' '));

function toSet(list) {
  var s = {};
  for (var i = 0; i < list.length; i++) s[list[i]] = true;
  return s;
}

// Words in any script we recognise (English and Nepali).
export function wordCount(text) {
  if (!text) return 0;
  var dev = text.match(DEVANAGARI_WORD);
  return tokenizeWords(text).length + (dev ? dev.length : 0);
}

export function readabilityLabel(score) {
  if (score >= 90) return 'Very easy';
  if (score >= 80) return 'Easy';
  if (score >= 70) return 'Fairly easy';
  if (score >= 60) return 'Plain English';
  if (score >= 50) return 'Fairly difficult';
  if (score >= 30) return 'Difficult';
  return 'Very difficult';
}

export function computeStats(paragraphs, longSentenceWords) {
  var limit = longSentenceWords || 30;
  var words = 0;
  var englishWords = 0;
  var characters = 0;
  var charactersNoSpaces = 0;
  var sentencesCount = 0;
  var syllables = 0;
  var letters = 0;
  var paraCount = 0;
  var buckets = [0, 0, 0, 0, 0];
  var longCount = 0;
  var freq = {};
  var unique = {};
  var contentWords = 0;
  var sentenceList = [];

  for (var p = 0; p < paragraphs.length; p++) {
    var para = paragraphs[p];
    var text = para.text || '';
    if (!/\S/.test(text)) continue;
    paraCount++;
    characters += text.length;
    charactersNoSpaces += text.replace(/\s/g, '').length;
    var dev = text.match(DEVANAGARI_WORD);
    if (dev) words += dev.length;
    var tokens = tokenizeWords(text);
    words += tokens.length;
    if (!isCheckable(text)) continue;
    englishWords += tokens.length;
    for (var t = 0; t < tokens.length; t++) {
      var w = tokens[t].word;
      if (/[A-Za-z]/.test(w)) {
        syllables += syllableCount(w);
        letters += w.replace(/[^A-Za-z\u00c0-\u024f]/g, '').length;
      }
      var lw = w.toLowerCase().replace(/\u2019/g, "'");
      if (/^[a-z][a-z'\-]+$/.test(lw) && !STOPWORDS[lw] && lw.length > 2) {
        contentWords++;
        unique[lw] = true;
        freq[lw] = (freq[lw] || 0) + 1;
      }
    }
    var sentences = splitSentences(text);
    for (var s = 0; s < sentences.length; s++) {
      var n = tokenizeWords(sentences[s].text).length;
      if (!n) continue;
      sentencesCount++;
      if (n <= 10) buckets[0]++;
      else if (n <= 20) buckets[1]++;
      else if (n <= 30) buckets[2]++;
      else if (n <= 40) buckets[3]++;
      else buckets[4]++;
      if (n > limit) longCount++;
      sentenceList.push({ pKey: para.key, pIndex: para.index, start: sentences[s].start, end: sentences[s].end, text: sentences[s].text, words: n });
    }
  }

  var avgSentence = sentencesCount ? englishWords / sentencesCount : 0;
  var syllablesPerWord = englishWords ? syllables / englishWords : 0;
  var flesch = sentencesCount && englishWords ? 206.835 - 1.015 * avgSentence - 84.6 * syllablesPerWord : null;
  var grade = sentencesCount && englishWords ? 0.39 * avgSentence + 11.8 * syllablesPerWord - 15.59 : null;
  if (flesch !== null) flesch = Math.max(0, Math.min(100, flesch));
  if (grade !== null) grade = Math.max(1, grade);

  var top = [];
  for (var k in freq) {
    if (Object.prototype.hasOwnProperty.call(freq, k) && freq[k] >= 3) top.push({ word: k, count: freq[k] });
  }
  top.sort(function (a, b) {
    return b.count - a.count || (a.word < b.word ? -1 : 1);
  });
  sentenceList.sort(function (a, b) {
    return b.words - a.words;
  });

  var uniqueCount = 0;
  for (var u in unique) if (Object.prototype.hasOwnProperty.call(unique, u)) uniqueCount++;

  return {
    words: words,
    englishWords: englishWords,
    characters: characters,
    charactersNoSpaces: charactersNoSpaces,
    sentences: sentencesCount,
    paragraphs: paraCount,
    readingMinutes: words / 238,
    speakingMinutes: words / 140,
    avgSentenceWords: avgSentence,
    avgWordLetters: englishWords ? letters / englishWords : 0,
    flesch: flesch,
    fleschLabel: flesch === null ? '' : readabilityLabel(flesch),
    grade: grade,
    longSentences: longCount,
    longLimit: limit,
    buckets: [
      { label: '1\u201310', count: buckets[0] },
      { label: '11\u201320', count: buckets[1] },
      { label: '21\u201330', count: buckets[2] },
      { label: '31\u201340', count: buckets[3] },
      { label: '41+', count: buckets[4] }
    ],
    uniquePercent: contentWords ? (uniqueCount / contentWords) * 100 : 0,
    topWords: top.slice(0, 6),
    longest: sentenceList.slice(0, 3)
  };
}

// Overall score, 0\u2013100: issues per 100 words weighted by category, mapped onto a curve
// so that a clean draft scores in the 90s and a draft with frequent errors in the 50s.
export function computeScore(issues, words) {
  if (!words) return null;
  var weighted = 0;
  for (var i = 0; i < issues.length; i++) {
    var cat = CATEGORIES[issues[i].category];
    weighted += cat ? cat.weight : 1;
  }
  var per100 = (weighted / Math.max(words, 30)) * 100;
  return Math.max(0, Math.min(100, Math.round(100 * Math.exp(-per100 / 27))));
}

export function scoreLabel(score) {
  if (score === null || score === undefined) return '';
  if (score >= 90) return 'Excellent';
  if (score >= 80) return 'Good';
  if (score >= 65) return 'Fair';
  return 'Needs work';
}
