// Claude (Anthropic API) client for AI rewriting and the optional AI deep check.
// The API key is entered by the user and kept only in this add-in's local storage.

import { httpRequest, parseJSON } from './http.js';
import { createIssue, CATEGORY_ORDER } from './issues.js';
import { searchPositions } from './text.js';

export var CLAUDE_ENDPOINT = 'https://api.anthropic.com/v1/messages';

export var CLAUDE_MODELS = [
  { id: 'claude-sonnet-5-5', label: 'Claude Sonnet 5.5 (balanced, recommended)' },
  { id: 'claude-haiku-5-5', label: 'Claude Haiku 5.5 (fastest, lowest cost)' },
  { id: 'claude-opus-5-5', label: 'Claude Opus 5.5 (most capable)' }
];

export var REWRITE_PRESETS = [
  { id: 'improve', label: 'Improve', instruction: 'Improve clarity, flow and word choice, and fix any grammar, spelling or punctuation errors.' },
  { id: 'grammar', label: 'Fix grammar', instruction: 'Correct grammar, spelling and punctuation only. Change as little as possible.' },
  { id: 'formal', label: 'Formal', instruction: 'Rewrite in a formal, professional tone suitable for official correspondence.' },
  { id: 'concise', label: 'Shorter', instruction: 'Make it more concise. Remove redundancy and filler without losing any information.' },
  { id: 'simplify', label: 'Simpler', instruction: 'Rewrite in plain English that is easy to understand, with short sentences and common words.' },
  { id: 'polite', label: 'Polite', instruction: 'Make the tone polite and courteous while keeping it professional.' },
  { id: 'expand', label: 'Expand', instruction: 'Expand the text with relevant explanation and smoother transitions. Do not invent facts, figures or names.' },
  { id: 'summary', label: 'Summarise', instruction: 'Summarise the text in a few clear sentences.' },
  { id: 'bullets', label: 'Bullet points', instruction: 'Turn the text into a concise bulleted list. Start each item on a new line with "\u2022 ".' },
  { id: 'nepali', label: 'To Nepali', instruction: 'Translate the text into Nepali (Devanagari script) in the formal register used in government documents. Keep numbers, units, names and technical terms accurate.' },
  { id: 'english', label: 'To English', instruction: 'Translate the text into clear, formal English.' }
];

var GOAL_DESCRIPTIONS = {
  general: 'a general audience',
  formal: 'formal, official writing such as government letters, notes and reports',
  academic: 'academic writing',
  business: 'business writing such as emails, proposals and memos',
  technical: 'technical engineering reports and specifications',
  casual: 'casual, friendly writing'
};

var VARIANTS = {
  'en-GB': 'British English',
  'en-US': 'American English',
  'en-AU': 'Australian English',
  'en-CA': 'Canadian English',
  'en-NZ': 'New Zealand English',
  'en-ZA': 'South African English'
};

export function variantName(lang) {
  return VARIANTS[lang] || 'English';
}

export function ClaudeClient(options) {
  options = options || {};
  this.http = options.http || httpRequest;
}

ClaudeClient.prototype.send = function (cfg) {
  var self = this;
  var body = {
    model: cfg.model,
    max_tokens: cfg.maxTokens || 8000,
    system: cfg.system,
    messages: cfg.messages
  };
  var outputConfig = {};
  if (cfg.effort) outputConfig.effort = cfg.effort;
  if (cfg.schema) outputConfig.format = { type: 'json_schema', schema: cfg.schema };
  if (cfg.effort || cfg.schema) body.output_config = outputConfig;

  return this.http({
    method: 'POST',
    url: CLAUDE_ENDPOINT,
    headers: {
      'content-type': 'application/json',
      'x-api-key': cfg.apiKey,
      'anthropic-version': '2023-06-01',
      'anthropic-dangerous-direct-browser-access': 'true'
    },
    body: JSON.stringify(body),
    timeout: cfg.timeout || 120000
  }).then(function (res) {
    var json = parseJSON(res.text);
    if (res.status === 200 && json) {
      var text = '';
      var content = json.content || [];
      for (var i = 0; i < content.length; i++) {
        if (content[i].type === 'text') text += content[i].text;
      }
      return { text: text, stopReason: json.stop_reason };
    }
    var apiMsg = json && json.error && json.error.message ? json.error.message : '';
    // Older or custom models may not accept effort / structured output: retry without them once.
    if (res.status === 400 && body.output_config && !cfg.retried && /effort|output_config|format|schema/i.test(apiMsg)) {
      var retry = {};
      for (var k in cfg) if (Object.prototype.hasOwnProperty.call(cfg, k)) retry[k] = cfg[k];
      retry.effort = null;
      retry.schema = null;
      retry.retried = true;
      retry.jsonFallback = !!cfg.schema;
      return self.send(retry);
    }
    var err = new Error(describeError(res.status, apiMsg));
    err.status = res.status;
    throw err;
  });
};

function describeError(status, apiMsg) {
  if (status === 401) return 'Claude rejected the API key. Check it in Settings.';
  if (status === 403) return 'This API key is not allowed to use that model. ' + (apiMsg || '');
  if (status === 404) return 'Model not found. Choose another model in Settings. ' + (apiMsg || '');
  if (status === 429) return 'Claude rate limit reached. Wait a moment and try again.';
  if (status === 529 || status === 503) return 'Claude is overloaded right now. Try again in a minute.';
  if (status === 0) return 'Could not reach the Claude API. Check your internet connection.';
  return 'Claude API error ' + status + (apiMsg ? ': ' + apiMsg : '');
}

export function rewriteSystemPrompt(settings) {
  return 'You are WriteAssist, a writing assistant inside Microsoft Word. You rewrite the text the user ' +
    'gives you exactly as instructed. Return only the rewritten text: no preface, no quotation marks around it, ' +
    'no Markdown formatting and no explanations. Keep the original meaning, facts, figures, names and technical ' +
    'terms. Write in ' + variantName(settings.language) + ' for ' + (GOAL_DESCRIPTIONS[settings.goal] || GOAL_DESCRIPTIONS.general) +
    '. Keep paragraph breaks unless the instruction says otherwise. If the text is already good, return it with minimal changes.';
}

export function cleanRewrite(text) {
  var t = (text || '').replace(/^\s+|\s+$/g, '');
  t = t.replace(/^<text>\s*/i, '').replace(/\s*<\/text>$/i, '');
  if (/^"[\s\S]*"$/.test(t) && t.indexOf('"', 1) === t.length - 1) t = t.slice(1, -1);
  return t;
}

ClaudeClient.prototype.rewrite = function (text, instruction, settings) {
  var ai = settings.ai || {};
  return this.send({
    apiKey: ai.apiKey,
    model: ai.customModel || ai.model,
    system: rewriteSystemPrompt(settings),
    messages: [{ role: 'user', content: 'Instruction: ' + instruction + '\n\n<text>\n' + text + '\n</text>' }],
    maxTokens: text.length > 6000 ? 16000 : 8000,
    effort: 'low'
  }).then(function (res) {
    var out = cleanRewrite(res.text);
    if (!out) throw new Error('Claude returned an empty response. Try again.');
    return out;
  });
};

export var DEEP_CHECK_SCHEMA = {
  type: 'object',
  properties: {
    issues: {
      type: 'array',
      items: {
        type: 'object',
        properties: {
          paragraph: { type: 'integer' },
          original: { type: 'string' },
          replacement: { type: 'string' },
          category: { type: 'string', enum: ['correctness', 'clarity', 'engagement', 'delivery'] },
          title: { type: 'string' },
          explanation: { type: 'string' }
        },
        required: ['paragraph', 'original', 'replacement', 'category', 'title', 'explanation'],
        additionalProperties: false
      }
    }
  },
  required: ['issues'],
  additionalProperties: false
};

export function deepCheckSystemPrompt(settings) {
  return 'You are an expert copy editor for ' + variantName(settings.language) + '. The writing is for ' +
    (GOAL_DESCRIPTIONS[settings.goal] || GOAL_DESCRIPTIONS.general) + '. Review the numbered paragraphs and report the ' +
    'most valuable edits a rule-based grammar checker would miss: grammar and agreement, wrong word choice, unclear or ' +
    'ambiguous phrasing, wordiness, and tone that does not suit the audience. Rules: (1) "original" must be copied ' +
    'verbatim from the paragraph and be as short as possible (at most 12 words); (2) "replacement" is the exact text that ' +
    'should replace it; (3) never change names, numbers, units, quotations or technical terms; (4) skip trivial or ' +
    'purely stylistic preferences; (5) report at most 20 issues, most important first; (6) title is 2-4 words, ' +
    'explanation is one short sentence. If nothing needs changing, return an empty list. Respond with JSON only, in ' +
    'the form {"issues":[{"paragraph":1,"original":"...","replacement":"...","category":"correctness|clarity|' +
    'engagement|delivery","title":"...","explanation":"..."}]}.';
}

function lenientJSON(text) {
  var direct = parseJSON(text);
  if (direct) return direct;
  var start = text.indexOf('{');
  var end = text.lastIndexOf('}');
  if (start !== -1 && end > start) return parseJSON(text.slice(start, end + 1));
  return null;
}

// paras: [{id, text}] -> {id: [issue templates]}
export function mapDeepCheck(json, paras) {
  var out = {};
  for (var p = 0; p < paras.length; p++) out[paras[p].id] = [];
  var list = (json && json.issues) || [];
  for (var i = 0; i < list.length; i++) {
    var it = list[i];
    var para = paras[(it.paragraph | 0) - 1];
    if (!para || typeof it.original !== 'string' || typeof it.replacement !== 'string') continue;
    var original = it.original;
    if (!original || original === it.replacement) continue;
    var positions = searchPositions(para.text, original);
    if (!positions.length) {
      var trimmed = original.replace(/^["'\u201c\u2018\s]+|["'\u201d\u2019\s]+$/g, '');
      if (trimmed && trimmed !== original) {
        positions = searchPositions(para.text, trimmed);
        original = trimmed;
      }
    }
    if (!positions.length) continue;
    var taken = out[para.id];
    var pos = -1;
    for (var k = 0; k < positions.length; k++) {
      var clash = false;
      for (var t = 0; t < taken.length; t++) {
        if (positions[k] < taken[t].offset + taken[t].length && taken[t].offset < positions[k] + original.length) clash = true;
      }
      if (!clash) {
        pos = positions[k];
        break;
      }
    }
    if (pos === -1) continue;
    var category = CATEGORY_ORDER.indexOf(String(it.category).toLowerCase()) !== -1 ? String(it.category).toLowerCase() : 'clarity';
    var issue = createIssue({
      source: 'ai',
      ruleId: 'WA_AI',
      type: 'ai',
      category: category,
      title: (it.title || 'AI suggestion').slice(0, 40),
      message: it.explanation || '',
      offset: pos,
      length: original.length,
      original: para.text.substr(pos, original.length),
      replacements: [it.replacement]
    });
    taken.push(issue);
  }
  return out;
}

ClaudeClient.prototype.deepCheck = function (paras, settings) {
  var ai = settings.ai || {};
  var numbered = [];
  for (var i = 0; i < paras.length; i++) numbered.push('[' + (i + 1) + '] ' + paras[i].text);
  return this.send({
    apiKey: ai.apiKey,
    model: ai.customModel || ai.model,
    system: deepCheckSystemPrompt(settings),
    messages: [{ role: 'user', content: 'Paragraphs:\n\n' + numbered.join('\n\n') }],
    maxTokens: 12000,
    effort: 'medium',
    schema: DEEP_CHECK_SCHEMA
  }).then(function (res) {
    var json = lenientJSON(res.text);
    if (!json) throw new Error('Claude returned suggestions in an unexpected format.');
    return mapDeepCheck(json, paras);
  });
};
