// LanguageTool client: spelling and grammar checks.
// Public API limits (dev.languagetool.org/public-http-api): 20 requests/min, 75 KB/min and
// 20 KB per request per IP. WriteAssist stays well below that with a rolling limiter.

import { httpRequest, formEncode, parseJSON } from './http.js';
import { createIssue } from './issues.js';
import { hasNonLatinScript, splitSentences } from './text.js';
import { delay } from './util.js';

export var LT_PUBLIC = 'https://api.languagetool.org/v2';
export var LT_PREMIUM = 'https://api.languagetoolplus.com/v2';

// Rules that are noisy in reports, letters and tables.
export var DEFAULT_DISABLED_RULES = [
  'PUNCTUATION_PARAGRAPH_END',
  'EN_QUOTES',
  'DASH_RULE',
  'TOO_LONG_SENTENCE',
  'WHITESPACE_PARAGRAPH'
];

export var CHUNK_CHARS = 6000;

export function RateLimiter(maxRequests, maxChars, windowMs, clock) {
  this.maxRequests = maxRequests;
  this.maxChars = maxChars;
  this.windowMs = windowMs;
  this.entries = [];
  this.now = (clock && clock.now) || function () {
    return Date.now();
  };
  this.sleep = (clock && clock.sleep) || delay;
}

RateLimiter.prototype.prune = function () {
  var cutoff = this.now() - this.windowMs;
  while (this.entries.length && this.entries[0].t <= cutoff) this.entries.shift();
};

RateLimiter.prototype.usage = function () {
  var chars = 0;
  for (var i = 0; i < this.entries.length; i++) chars += this.entries[i].size;
  return { requests: this.entries.length, chars: chars };
};

// Resolves once a request of `size` characters fits in the window; records it.
RateLimiter.prototype.acquire = function (size, onWait) {
  var self = this;
  function attempt() {
    self.prune();
    var u = self.usage();
    var fits = u.requests < self.maxRequests && (u.chars + size <= self.maxChars || u.requests === 0);
    if (fits) {
      self.entries.push({ t: self.now(), size: size });
      return Promise.resolve();
    }
    var waitMs = Math.max(250, self.entries[0].t + self.windowMs - self.now() + 50);
    if (onWait) onWait(waitMs);
    return self.sleep(waitMs).then(attempt);
  }
  return attempt();
};

// Group paragraphs into request-sized chunks separated by blank lines.
// paras: [{id, text}] -> [{text, segments: [{id, start, length, paraOffset}]}]
export function buildChunks(paras, maxChars) {
  var limit = maxChars || CHUNK_CHARS;
  var chunks = [];
  var cur = { text: '', segments: [] };
  function flush() {
    if (cur.segments.length) chunks.push(cur);
    cur = { text: '', segments: [] };
  }
  for (var i = 0; i < paras.length; i++) {
    var p = paras[i];
    if (p.text.length > limit) {
      flush();
      var pieces = splitLong(p.text, limit);
      for (var j = 0; j < pieces.length; j++) {
        chunks.push({ text: pieces[j].text, segments: [{ id: p.id, start: 0, length: pieces[j].text.length, paraOffset: pieces[j].start }] });
      }
      continue;
    }
    var sep = cur.text ? '\n\n' : '';
    if (cur.text.length + sep.length + p.text.length > limit) {
      flush();
      sep = '';
    }
    var start = cur.text.length + sep.length;
    cur.text += sep + p.text;
    cur.segments.push({ id: p.id, start: start, length: p.text.length, paraOffset: 0 });
  }
  flush();
  return chunks;
}

function splitLong(text, limit) {
  var sentences = splitSentences(text);
  var pieces = [];
  var curStart = 0;
  var curEnd = 0;
  for (var i = 0; i < sentences.length; i++) {
    var s = sentences[i];
    if (s.end - curStart > limit && curEnd > curStart) {
      pieces.push({ start: curStart, text: text.slice(curStart, curEnd) });
      curStart = s.start;
    }
    curEnd = s.end;
    while (curEnd - curStart > limit) {
      // a single gigantic "sentence": hard split on whitespace
      var cut = text.lastIndexOf(' ', curStart + limit);
      if (cut <= curStart) cut = curStart + limit;
      pieces.push({ start: curStart, text: text.slice(curStart, cut) });
      curStart = cut;
    }
  }
  if (curEnd > curStart) pieces.push({ start: curStart, text: text.slice(curStart, curEnd) });
  return pieces;
}

export function classifyMatch(rule) {
  var id = (rule && rule.id) || '';
  var cat = (rule && rule.category && rule.category.id) || '';
  var issueType = (rule && rule.issueType) || '';
  if (issueType === 'misspelling' || cat === 'TYPOS' || /MORFOLOGIK|SPELLER|HUNSPELL/.test(id)) return 'spelling';
  if (issueType === 'locale-violation' || cat === 'BRITISH_ENGLISH' || cat === 'AMERICAN_ENGLISH') return 'spelling';
  if (cat === 'REPETITIONS_STYLE' || /REPEAT_BEGINNING|REPETITION_STYLE/.test(id)) return 'repetition';
  if (cat === 'PUNCTUATION' || cat === 'TYPOGRAPHY' || issueType === 'typographical' || issueType === 'whitespace' ||
      /WHITESPACE|COMMA_PARENTHESIS|PUNCTUATION|DOUBLE_PUNCT/.test(id)) return 'punctuation';
  if (cat === 'REDUNDANCY') return 'redundancy';
  if (cat === 'PLAIN_ENGLISH' || /WORDINESS|PLAIN_ENGLISH/.test(id)) return 'wordy';
  if (issueType === 'register' || cat === 'NONSTANDARD_PHRASES' || /INFORMAL|COLLOQUIAL/.test(id)) return 'formality';
  if (cat === 'STYLE' || issueType === 'style') return 'style';
  return 'grammar';
}

export function matchToIssue(match, localOffset, paraText) {
  var rule = match.rule || {};
  var type = classifyMatch(rule);
  var offset = localOffset;
  var length = match.length;
  var prefix = '';
  var suffix = '';
  if (length === 0) {
    // an insertion point (e.g. a missing comma): widen to a neighbouring character so the
    // span can be located and replaced in Word
    if (offset > 0) {
      offset -= 1;
      prefix = paraText.charAt(offset);
    } else {
      suffix = paraText.charAt(0);
    }
    length = 1;
  }
  var original = paraText.substr(offset, length);
  var reps = [];
  var list = match.replacements || [];
  for (var i = 0; i < list.length && reps.length < 5; i++) {
    var v = list[i] && list[i].value;
    if (typeof v === 'string') v = prefix + v + suffix;
    if (typeof v === 'string' && v !== original && reps.indexOf(v) === -1) reps.push(v);
  }
  var issue = createIssue({
    source: 'lt',
    ruleId: rule.id || 'LT',
    type: type,
    message: match.message || (rule.description || ''),
    offset: offset,
    length: length,
    original: original,
    replacements: reps
  });
  if (match.shortMessage && type !== 'spelling') issue.title = match.shortMessage;
  if (rule.description) issue.ruleDescription = rule.description;
  return issue;
}

// Map one LanguageTool response back onto paragraphs. Returns {id: [issue templates]}.
export function mapMatches(chunk, matches, textsById) {
  var out = {};
  for (var s = 0; s < chunk.segments.length; s++) {
    if (!out[chunk.segments[s].id]) out[chunk.segments[s].id] = [];
  }
  for (var i = 0; i < matches.length; i++) {
    var m = matches[i];
    if (typeof m.offset !== 'number' || typeof m.length !== 'number') continue;
    for (var j = 0; j < chunk.segments.length; j++) {
      var seg = chunk.segments[j];
      if (m.offset >= seg.start && m.offset + m.length <= seg.start + seg.length) {
        var local = m.offset - seg.start + seg.paraOffset;
        var paraText = textsById[seg.id];
        var original = paraText.substr(local, m.length);
        if (!original && m.length > 0) break;
        if (hasNonLatinScript(original)) break; // e.g. Devanagari words inside English text
        out[seg.id].push(matchToIssue(m, local, paraText));
        break;
      }
    }
  }
  return out;
}

export function LanguageToolClient(options) {
  options = options || {};
  this.http = options.http || httpRequest;
  this.clock = options.clock;
  this.publicLimiter = new RateLimiter(12, 60000, 60000, this.clock);
  this.premiumLimiter = new RateLimiter(60, 240000, 60000, this.clock);
}

LanguageToolClient.prototype.limiterFor = function (server) {
  if (!server || server.indexOf('api.languagetool.org') !== -1) return this.publicLimiter;
  if (server.indexOf('languagetoolplus.com') !== -1) return this.premiumLimiter;
  return null; // self-hosted server: no limit
};

// Returns the raw matches array. Throws errors tagged with .status / .network / .rateLimited.
LanguageToolClient.prototype.check = function (text, params, onWait) {
  var self = this;
  var server = (params.server || LT_PUBLIC).replace(/\/+$/, '');
  var limiter = this.limiterFor(server);
  var body = formEncode({
    text: text,
    language: params.language || 'en-GB',
    level: params.picky ? 'picky' : 'default',
    disabledRules: (params.disabledRules || []).join(','),
    username: params.username,
    apiKey: params.apiKey
  });
  var ready = limiter ? limiter.acquire(text.length, onWait) : Promise.resolve();
  return ready.then(function () {
    return self.http({
      method: 'POST',
      url: server + '/check',
      headers: { 'Content-Type': 'application/x-www-form-urlencoded', Accept: 'application/json' },
      body: body,
      timeout: 45000
    });
  }).then(function (res) {
    if (res.status === 200) {
      var json = parseJSON(res.text);
      if (!json) throw tagged(new Error('LanguageTool returned an unreadable response.'), res.status);
      return json.matches || [];
    }
    var msg = (res.text || '').slice(0, 200);
    if (res.status === 429) {
      var e = tagged(new Error('LanguageTool is busy (too many requests).'), 429);
      e.rateLimited = true;
      throw e;
    }
    if (res.status === 413) throw tagged(new Error('The text was too long for one request.'), 413);
    if (res.status === 401 || res.status === 403) {
      throw tagged(new Error('LanguageTool rejected the credentials. Check the username and API key in Settings.'), res.status);
    }
    if (res.status === 0) {
      var ne = tagged(new Error('Could not reach LanguageTool.'), 0);
      ne.network = true;
      throw ne;
    }
    throw tagged(new Error('LanguageTool error ' + res.status + (msg ? ': ' + msg : '')), res.status);
  });
};

function tagged(err, status) {
  err.status = status;
  return err;
}
