// Settings are stored in this add-in's local storage on the user's computer.

import { storageGet, storageSet, storageRemove, deepClone } from './util.js';
import { GOALS } from './rules.js';
import { LT_PUBLIC, LT_PREMIUM, DEFAULT_DISABLED_RULES } from './languagetool.js';
import { NEPAL_TERMS } from './rules-data.js';

export var SETTINGS_KEY = 'writeassist.settings.v1';
export var VERSION = '1.0.0';

export var LANGUAGES = [
  { id: 'en-GB', label: 'English (UK)' },
  { id: 'en-US', label: 'English (US)' },
  { id: 'en-AU', label: 'English (Australia)' },
  { id: 'en-CA', label: 'English (Canada)' },
  { id: 'en-NZ', label: 'English (New Zealand)' },
  { id: 'en-ZA', label: 'English (South Africa)' }
];

export function defaultSettings() {
  return {
    version: 1,
    language: 'en-GB',
    goal: 'formal',
    checks: {},
    autoCheck: true,
    liveCheck: true,
    underlines: true,
    useLanguageTool: true,
    lt: { server: 'public', customUrl: '', username: '', apiKey: '' },
    ignoreUppercase: true,
    ignoreWithNumbers: true,
    nepalTerms: true,
    disabledRules: {},
    dictionary: [],
    ai: { apiKey: '', model: 'claude-sonnet-5-5', customModel: '', deepCheck: false }
  };
}

function mergeInto(base, stored) {
  if (!stored || typeof stored !== 'object') return base;
  for (var k in stored) {
    if (!Object.prototype.hasOwnProperty.call(stored, k)) continue;
    var v = stored[k];
    if (v && typeof v === 'object' && !(v instanceof Array) && base[k] && typeof base[k] === 'object' && !(base[k] instanceof Array)) {
      mergeInto(base[k], v);
    } else {
      base[k] = v;
    }
  }
  return base;
}

export function loadSettings() {
  var s = mergeInto(defaultSettings(), storageGet(SETTINGS_KEY, null));
  if (!GOALS[s.goal]) s.goal = 'formal';
  if (!(s.dictionary instanceof Array)) s.dictionary = [];
  return s;
}

export function saveSettings(settings) {
  return storageSet(SETTINGS_KEY, settings);
}

export function resetSettings() {
  storageRemove(SETTINGS_KEY);
  return defaultSettings();
}

export function cloneSettings(s) {
  return deepClone(s);
}

export function ltServerUrl(settings) {
  var lt = settings.lt || {};
  if (lt.server === 'premium') return LT_PREMIUM;
  if (lt.server === 'custom' && lt.customUrl) return lt.customUrl.replace(/\/+$/, '').replace(/\/check$/, '');
  return LT_PUBLIC;
}

// Rules the user turns off are filtered on this computer rather than sent to LanguageTool,
// so turning a rule on or off never forces the whole document to be checked again.
export function ltParams(settings) {
  var disabled = DEFAULT_DISABLED_RULES.slice();
  var goal = GOALS[settings.goal] || GOALS.general;
  var lt = settings.lt || {};
  return {
    server: ltServerUrl(settings),
    language: settings.language,
    picky: goal.picky,
    disabledRules: disabled,
    username: lt.server === 'premium' ? lt.username : '',
    apiKey: lt.server === 'premium' ? lt.apiKey : ''
  };
}

// Key that changes whenever LanguageTool would answer differently.
export function ltSignature(settings) {
  var p = ltParams(settings);
  return [p.server, p.language, p.picky ? 'picky' : 'default', p.disabledRules.join(',')].join('|');
}

export function aiSignature(settings) {
  var ai = settings.ai || {};
  return [ai.customModel || ai.model, settings.language, settings.goal].join('|');
}

var nepalSet = null;
function getNepalSet() {
  if (!nepalSet) {
    nepalSet = {};
    for (var i = 0; i < NEPAL_TERMS.length; i++) nepalSet[NEPAL_TERMS[i].toLowerCase()] = true;
  }
  return nepalSet;
}

// Spelling filter applied to LanguageTool results (and AI spelling notes).
export function makeSpellingFilter(settings) {
  var dict = {};
  var words = settings.dictionary || [];
  for (var i = 0; i < words.length; i++) dict[String(words[i]).toLowerCase()] = true;
  var nepal = settings.nepalTerms ? getNepalSet() : null;
  return function (issue) {
    if (issue.type !== 'spelling') return true;
    var word = String(issue.original || '').replace(/^[^A-Za-z0-9\u00c0-\u024f]+|[^A-Za-z0-9\u00c0-\u024f]+$/g, '');
    if (!word) return true;
    var lower = word.toLowerCase();
    if (dict[lower]) return false;
    if (nepal && nepal[lower]) return false;
    if (settings.ignoreUppercase && word.length > 1 && word === word.toUpperCase() && /[A-Z]/.test(word)) return false;
    if (settings.ignoreWithNumbers && /[0-9]/.test(word)) return false;
    return true;
  };
}
