/* global Office */
// Entry point for the task pane (inside Word) and the browser demo.

import { App } from './ui/app.js';
import { WordAdapter } from './adapters/word.js';
import { DemoAdapter } from './adapters/demo.js';

function root() {
  return document.getElementById('wa-root');
}

function showMessage(title, body, linkText, linkHref) {
  var el = root();
  if (!el) return;
  el.className = 'wa';
  el.innerHTML = '';
  var box = document.createElement('div');
  box.className = 'wa-empty wa-outside';
  var h = document.createElement('h2');
  h.className = 'wa-empty-title';
  h.appendChild(document.createTextNode(title));
  var p = document.createElement('p');
  p.appendChild(document.createTextNode(body));
  box.appendChild(h);
  box.appendChild(p);
  if (linkText) {
    var a = document.createElement('a');
    a.className = 'wa-btn wa-btn-primary';
    a.href = linkHref;
    a.appendChild(document.createTextNode(linkText));
    box.appendChild(a);
  }
  el.appendChild(box);
}

function start(adapter) {
  var app = new App(root(), adapter);
  window.WriteAssistApp = app;
  app.mount();
}

function boot() {
  var mode = document.documentElement.getAttribute('data-mode');
  if (mode === 'demo') {
    start(new DemoAdapter(document.getElementById('demo-doc'), document.getElementById('demo-backdrop')));
    return;
  }
  if (typeof Office === 'undefined' || !Office.onReady) {
    showMessage('Office could not load', 'WriteAssist needs the Office JavaScript library from Microsoft. Check your internet connection, then close and reopen WriteAssist.');
    return;
  }
  Office.onReady(function (info) {
    if (info && info.host === Office.HostType.Word) {
      start(new WordAdapter());
    } else {
      showMessage('Open WriteAssist from Word', 'This page is the WriteAssist panel and only works inside Microsoft Word. You can try it in your browser with the demo.', 'Open the demo', 'demo.html');
    }
  });
}

window.onerror = function (message) {
  var el = root();
  if (el && !el.querySelector('.wa-crash')) {
    var bar = document.createElement('div');
    bar.className = 'wa-crash';
    bar.setAttribute('role', 'alert');
    bar.appendChild(document.createTextNode('Something went wrong: ' + message + '. Close and reopen WriteAssist; if it keeps happening, clear the Office add-in cache.'));
    el.insertBefore(bar, el.firstChild);
  }
  return false;
};

if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', boot);
else boot();
