// Issue model shared by every engine (LanguageTool, local rules, Claude).
//
// An issue always points at a span inside ONE paragraph:
//   { id, source, ruleId, type, category, title, message, offset, length,
//     original, replacements[], sentenceLevel, pKey, pIndex }

import { uid } from './util.js';

export var CATEGORY_ORDER = ['correctness', 'clarity', 'engagement', 'delivery'];

export var CATEGORIES = {
  correctness: { label: 'Correctness', hint: 'Spelling, grammar and punctuation', weight: 4, critique: 'Red', subtitleRes: 'WA.Sub.Correctness' },
  clarity: { label: 'Clarity', hint: 'Wordiness, long sentences and passive voice', weight: 2, critique: 'Blue', subtitleRes: 'WA.Sub.Clarity' },
  engagement: { label: 'Engagement', hint: 'Weak words, clich\u00e9s and repetition', weight: 1, critique: 'Green', subtitleRes: 'WA.Sub.Engagement' },
  delivery: { label: 'Delivery', hint: 'Tone, formality and standard phrasing', weight: 1.5, critique: 'Lavender', subtitleRes: 'WA.Sub.Delivery' }
};

export var TYPES = {
  spelling: { label: 'Spelling', category: 'correctness', titleRes: 'WA.Title.Spelling' },
  grammar: { label: 'Grammar', category: 'correctness', titleRes: 'WA.Title.Grammar' },
  punctuation: { label: 'Punctuation', category: 'correctness', titleRes: 'WA.Title.Punctuation' },
  wordy: { label: 'Wordy phrase', category: 'clarity', titleRes: 'WA.Title.Wordy' },
  redundancy: { label: 'Redundancy', category: 'clarity', titleRes: 'WA.Title.Wordy' },
  passive: { label: 'Passive voice', category: 'clarity', titleRes: 'WA.Title.Passive' },
  'long-sentence': { label: 'Long sentence', category: 'clarity', titleRes: 'WA.Title.Long' },
  'weak-word': { label: 'Weak word', category: 'engagement', titleRes: 'WA.Title.Word' },
  cliche: { label: 'Clich\u00e9', category: 'engagement', titleRes: 'WA.Title.Word' },
  repetition: { label: 'Repetition', category: 'engagement', titleRes: 'WA.Title.Word' },
  style: { label: 'Style', category: 'engagement', titleRes: 'WA.Title.Word' },
  formality: { label: 'Formality', category: 'delivery', titleRes: 'WA.Title.Tone' },
  nonstandard: { label: 'Nonstandard phrasing', category: 'delivery', titleRes: 'WA.Title.Tone' },
  tone: { label: 'Tone', category: 'delivery', titleRes: 'WA.Title.Tone' },
  ai: { label: 'AI suggestion', category: 'clarity', titleRes: 'WA.Title.AI' }
};

export function typeInfo(type) {
  return TYPES[type] || TYPES.style;
}

export function createIssue(fields) {
  var t = typeInfo(fields.type);
  var issue = {
    id: uid('iss'),
    source: fields.source || 'local',
    ruleId: fields.ruleId || fields.type,
    type: fields.type,
    category: fields.category || t.category,
    title: fields.title || t.label,
    message: fields.message || '',
    offset: fields.offset,
    length: fields.length,
    original: fields.original,
    replacements: (fields.replacements || []).slice(0, 5),
    sentenceLevel: !!fields.sentenceLevel,
    pKey: fields.pKey,
    pIndex: fields.pIndex
  };
  return issue;
}

// Copy an issue template (stored per paragraph text) into a live issue for a paragraph.
export function instantiate(template, pKey, pIndex) {
  var copy = {};
  for (var k in template) {
    if (Object.prototype.hasOwnProperty.call(template, k)) copy[k] = template[k];
  }
  copy.replacements = (template.replacements || []).slice();
  copy.pKey = pKey;
  copy.pIndex = pIndex;
  return copy;
}

// A stable fingerprint used to remember dismissed suggestions across re-checks.
export function signature(issue, paragraphText) {
  var before = paragraphText.slice(Math.max(0, issue.offset - 16), issue.offset);
  var after = paragraphText.slice(issue.offset + issue.length, issue.offset + issue.length + 16);
  return [issue.ruleId, issue.original, before, after].join('\u0001');
}

export function applyEdit(text, start, end, replacement) {
  return text.slice(0, start) + replacement + text.slice(end);
}

// After replacing [start, end) with `newLength` characters, move the remaining issues of
// the same paragraph. Issues that overlap the edited span are dropped.
export function shiftIssues(issues, start, end, newLength) {
  var delta = newLength - (end - start);
  var out = [];
  for (var i = 0; i < issues.length; i++) {
    var is = issues[i];
    var isEnd = is.offset + is.length;
    if (isEnd <= start) {
      out.push(is);
    } else if (is.offset >= end) {
      is.offset += delta;
      out.push(is);
    } else if (is.sentenceLevel && is.offset <= start && isEnd >= end) {
      // a sentence-level note (long sentence, passive voice) survives an edit inside it
      is.length += delta;
      out.push(is);
    }
  }
  return out;
}

function overlaps(a, b) {
  var aEnd = a.offset + Math.max(1, a.length);
  var bEnd = b.offset + Math.max(1, b.length);
  return a.offset < bEnd && b.offset < aEnd;
}

// Merge issues from several engines for one paragraph. Earlier lists win: an issue from
// a later list is dropped when it overlaps an earlier one of the same category, or when
// it targets the exact same span.
export function mergeIssueLists(lists) {
  var merged = [];
  for (var l = 0; l < lists.length; l++) {
    var list = lists[l] || [];
    for (var i = 0; i < list.length; i++) {
      var cand = list[i];
      var clash = false;
      for (var j = 0; j < merged.length; j++) {
        var ex = merged[j];
        if (cand.sentenceLevel || ex.sentenceLevel) {
          if (cand.sentenceLevel && ex.sentenceLevel && cand.type === ex.type && overlaps(cand, ex)) {
            clash = true;
            break;
          }
          continue;
        }
        if (!overlaps(cand, ex)) continue;
        if (cand.category === ex.category || (cand.offset === ex.offset && cand.length === ex.length)) {
          clash = true;
          break;
        }
        // a correctness fix always wins over a style note on the same words
        if (ex.category === 'correctness') {
          clash = true;
          break;
        }
      }
      if (!clash) merged.push(cand);
    }
  }
  merged.sort(function (a, b) {
    return a.offset - b.offset || a.length - b.length;
  });
  return merged;
}

export function sortIssues(issues) {
  return issues.sort(function (a, b) {
    return a.pIndex - b.pIndex || a.offset - b.offset || CATEGORY_ORDER.indexOf(a.category) - CATEGORY_ORDER.indexOf(b.category);
  });
}

export function countByCategory(issues) {
  var counts = { all: issues.length, correctness: 0, clarity: 0, engagement: 0, delivery: 0 };
  for (var i = 0; i < issues.length; i++) {
    counts[issues[i].category] = (counts[issues[i].category] || 0) + 1;
  }
  return counts;
}

// Keep fixes in priority (input) order, drop any that overlap an earlier one, and return
// them sorted from the end of the paragraph backwards so earlier offsets stay valid.
export function pickNonOverlapping(fixes) {
  var chosen = [];
  for (var i = 0; i < fixes.length; i++) {
    var f = fixes[i];
    var clash = false;
    for (var j = 0; j < chosen.length; j++) {
      if (f.start < chosen[j].end && chosen[j].start < f.end) {
        clash = true;
        break;
      }
    }
    if (!clash) chosen.push(f);
  }
  return chosen.sort(function (a, b) {
    return b.start - a.start;
  });
}
