// Inline SVG icons (16px grid, drawn for WriteAssist). currentColor keeps them theme-aware.

function svg(body, size) {
  var s = size || 16;
  return '<svg class="wa-ico" width="' + s + '" height="' + s + '" viewBox="0 0 16 16" fill="none" ' +
    'stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false">' +
    body + '</svg>';
}

