App.prototype.saveKey = function () {
  var input = qs(this.root, '#wa-key-input');
  var value = input ? input.value.replace(/\s/g, '') : '';
  if (!value) {
    this.toast('Paste your API key first.');
    return;
  }
  this.settings.ai.apiKey = value;
  this.persist();
  this.toast('API key saved on this computer.');
  this.render();
};

App.prototype.grabSelection = function () {
  var self = this;
  return this.adapter.getSelectionText().then(function (text) {
    var clean = (text || '').replace(/^\s+|\s+$/g, '');
    if (!clean) {
      self.state.rewrite.error = 'Select some text in your document first.';
    } else {
      self.state.rewrite.source = clean;
      self.state.rewrite.error = '';
    }
    self.renderRewrite();
    return clean;
  }, function (err) {
    self.state.rewrite.error = errorMessage(err);
    self.renderRewrite();
    return '';
  });
};

App.prototype.runRewrite = function (presetId) {
  var self = this;
  var rw = this.state.rewrite;
  if (rw.busy) return Promise.resolve();
  var instruction;
  if (presetId === 'custom') {
    var box = qs(this.root, '#wa-custom-instruction');
    rw.custom = box ? box.value : rw.custom;
    instruction = (rw.custom || '').replace(/^\s+|\s+$/g, '');
    if (!instruction) {
      rw.error = 'Describe the change you want, or choose one of the actions above.';
      this.renderRewrite();
      return Promise.resolve();
    }
  } else {
    for (var i = 0; i < REWRITE_PRESETS.length; i++) if (REWRITE_PRESETS[i].id === presetId) instruction = REWRITE_PRESETS[i].instruction;
    if (!instruction) instruction = presetId;
  }
  rw.lastInstruction = presetId === 'custom' ? instruction : presetId;
  // Prefer a fresh selection; fall back to the text already shown.
  return this.adapter.getSelectionText().then(function (sel) {
    var clean = (sel || '').replace(/^\s+|\s+$/g, '');
    if (clean) rw.source = clean;
    if (!rw.source) {
      rw.error = 'Select some text in your document first.';
      self.renderRewrite();
      return null;
    }
    rw.busy = true;
    rw.error = '';
    rw.result = '';
    self.renderRewrite();
    return self.claude.rewrite(rw.source, instruction, self.settings).then(function (out) {
      rw.result = out;
    }, function (err) {
      rw.error = errorMessage(err);
    }).then(function () {
      rw.busy = false;
      self.renderRewrite();
    });
  }, function (err) {
    rw.error = errorMessage(err);
    self.renderRewrite();
  });
};

App.prototype.rewriteReplace = function () {
  var self = this;
  var rw = this.state.rewrite;
  if (!rw.result) return Promise.resolve();
  return this.adapter.replaceSelection(rw.source, rw.result).then(function (res) {
    if (res === 'ok') {
      rw.source = rw.result;
      self.toast('Replaced. Undo in Word with Ctrl+Z.');
    } else {
      self.toast('Select the original text again, then choose Replace selection.');
    }
  }, function (err) {
    self.toast(errorMessage(err));
  });
};

App.prototype.rewriteInsert = function () {
  var self = this;
  var rw = this.state.rewrite;
  if (!rw.result) return Promise.resolve();
  return this.adapter.insertAfterSelection(rw.result).then(function () {
    self.toast('Inserted below the selection.');
  }, function (err) {
    self.toast(errorMessage(err));
  });
};

App.prototype.rewriteCopy = function () {
  var self = this;
  return copyText(this.state.rewrite.result).then(function () {
    self.toast('Copied.');
  }, function (err) {
    self.toast(errorMessage(err));
  });
};

