App.prototype.persist = function () {
  saveSettings(this.settings);
};

App.prototype.setSetting = function (path, value) {
  var parts = path.split('.');
  var obj = this.settings;
  for (var i = 0; i < parts.length - 1; i++) {
    if (!obj[parts[i]] || typeof obj[parts[i]] !== 'object') obj[parts[i]] = {};
    obj = obj[parts[i]];
  }
  var last = parts[parts.length - 1];
  var old = obj[last];
  obj[last] = value;
  if (path === 'goal') this.settings.checks = {};
  this.persist();

  var needsCheck = /^(language|goal|useLanguageTool|lt\.|ai\.deepCheck|ai\.model|ai\.customModel)/.test(path);
  var needsLocal = /^checks\./.test(path);
  var needsCompose = /^(ignoreUppercase|ignoreWithNumbers|nepalTerms)$/.test(path);

  if (path === 'underlines') {
    if (value) {
      this.annSynced = {};
      this.annSync();
    } else {
      this.adapter.clearAnnotations().then(null, function () {});
      this.annSynced = {};
    }
  }
  if (needsCheck && this.state.hasChecked && old !== value) {
    this.runCheck(this.state.scope);
  } else if (needsLocal) {
    this.refreshLocal();
  } else if (needsCompose) {
    this.recompose();
    this.renderHeader();
    this.annSync();
  }
  if (this.state.tab === 'settings') this.renderSettings();
  else if (this.state.tab === 'review') this.renderReview();
};

App.prototype.setAutoOpen = function (on) {
  var self = this;
  this.adapter.setAutoOpen(on).then(function () {
    self.toast(on ? 'WriteAssist will open with this document. Save the document to keep this.' : 'WriteAssist won\u2019t open automatically with this document.');
  }, function (err) {
    self.toast(errorMessage(err));
    self.renderSettings();
  });
};

