/* global Word, Office */
// Bridge between WriteAssist and the Word document (Office JavaScript API).
//
// Only WordApi 1.1 is required, so the add-in runs in Office 2016 and later. Newer
// requirement sets are feature-detected:
//   1.3  precise ranges for extra-space fixes and long-sentence selection
//   1.4  inserting review comments
//   1.6  stable paragraph IDs and change events (live checking)
//   1.7  in-document underlines (annotations, Microsoft 365)
//   1.8  suggestion pop-ups on the underlines

import { findSearchWindow, escapeWordSearch, isSearchable, isBlank, occurrenceIndex } from '../core/text.js';
import { CATEGORIES, typeInfo, pickNonOverlapping } from '../core/issues.js';

function isSet(name, version) {
  try {
    return !!(Office.context.requirements && Office.context.requirements.isSetSupported(name, version));
  } catch (e) {
    return false;
  }
}

export function detectCapabilities() {
  return {
    api13: isSet('WordApi', '1.3'),
    api14: isSet('WordApi', '1.4'),
    api16: isSet('WordApi', '1.6'),
    annotations: isSet('WordApi', '1.7'),
    popups: isSet('WordApi', '1.8'),
    comments: isSet('WordApi', '1.4'),
    documentSettings: !!(Office.context && Office.context.document && Office.context.document.settings),
    platform: (Office.context && Office.context.platform) || ''
  };
}

function norm(s) {
  return String(s || '')
    .replace(/[\u2018\u2019\u201a\u201b]/g, "'")
    .replace(/[\u201c\u201d\u201e\u201f]/g, '"')
    .replace(/[\s\u00a0\u000b]+/g, ' ');
}

export function WordAdapter() {
  this.kind = 'word';
  this.caps = detectCapabilities();
  this.annotationsWorking = this.caps.annotations;
}

WordAdapter.prototype.paragraphFields = function () {
  return this.caps.api16 ? 'items/text,items/uniqueLocalId' : 'items/text';
};

function keyFor(caps, p, i) {
  return caps.api16 && p.uniqueLocalId ? p.uniqueLocalId : 'i' + i;
}

// Returns [{key, index, text}] for the whole document or only the selected paragraphs.
WordAdapter.prototype.readParagraphs = function (scope) {
  var self = this;
  var caps = this.caps;
  return Word.run(async function (context) {
    var paras = context.document.body.paragraphs;
    paras.load(self.paragraphFields());
    var sel = null;
    if (scope === 'selection') {
      sel = context.document.getSelection().paragraphs;
      sel.load(self.paragraphFields());
    }
    await context.sync();
    var all = [];
    for (var i = 0; i < paras.items.length; i++) {
      var p = paras.items[i];
      all.push({ key: keyFor(caps, p, i), index: i, text: p.text || '' });
    }
    if (!sel) return all;
    return pickSelected(all, sel.items, caps);
  });
};

function pickSelected(all, selItems, caps) {
  if (!selItems.length) return [];
  if (caps.api16) {
    var ids = {};
    for (var i = 0; i < selItems.length; i++) ids[selItems[i].uniqueLocalId] = true;
    var out = [];
    for (var j = 0; j < all.length; j++) if (ids[all[j].key]) out.push(all[j]);
    if (out.length) return out;
  }
  // match the selected paragraphs as a contiguous run of the document's paragraphs
  var first = selItems[0].text;
  for (var s = 0; s < all.length; s++) {
    if (all[s].text !== first) continue;
    var ok = true;
    for (var k = 1; k < selItems.length; k++) {
      if (!all[s + k] || all[s + k].text !== selItems[k].text) {
        ok = false;
        break;
      }
    }
    if (ok) return all.slice(s, s + selItems.length);
  }
  return [];
}

// Locate the live paragraph for a reference {key, index, text} among loaded items.
export function findParagraph(items, caps, ref) {
  var i;
  if (caps.api16 && ref.key && ref.key.charAt(0) !== 'i') {
    for (i = 0; i < items.length; i++) {
      if (items[i].uniqueLocalId === ref.key) return { p: items[i], index: i };
    }
  } else if (items[ref.index] && items[ref.index].text === ref.text) {
    return { p: items[ref.index], index: ref.index };
  }
  var best = -1;
  var bestDist = Infinity;
  for (i = 0; i < items.length; i++) {
    if (items[i].text === ref.text) {
      var d = Math.abs(i - ref.index);
      if (d < bestDist) {
        best = i;
        bestDist = d;
      }
    }
  }
  if (best !== -1) return { p: items[best], index: best };
  if (!caps.api16 && items[ref.index]) return { p: items[ref.index], index: ref.index, changed: true };
  return null;
}

// Resolve several spans of one paragraph to Word ranges using as few round trips as possible.
// spans: [{start, end}] -> Promise<[Range|null]>
export async function findRanges(context, caps, paragraph, text, spans, nested) {
  var results = [];
  var jobs = [];
  var i;
  for (i = 0; i < spans.length; i++) {
    results.push(null);
    var start = spans[i].start;
    var end = spans[i].end;
    if (end <= start) continue;
    var target = text.slice(start, end);
    if (!isSearchable(target)) {
      if (!nested && end - start > 160) jobs.push({ i: i, long: true, start: start, end: end });
      continue;
    }
    var win = findSearchWindow(text, start, end);
    if (!win) continue;
    jobs.push({ i: i, start: start, end: end, target: target, win: win, winText: text.slice(win.start, win.end) });
  }

  // Long spans (whole sentences): resolve a head and a tail and join them.
  var longJobs = [];
  for (i = 0; i < jobs.length; i++) {
    if (!jobs[i].long) continue;
    var j = jobs[i];
    var headEnd = Math.min(j.end, j.start + 80);
    var tailStart = Math.max(j.start, j.end - 80);
    longJobs.push(j);
    j.parts = [{ start: j.start, end: headEnd }, { start: tailStart, end: j.end }];
  }
  if (longJobs.length) {
    var partSpans = [];
    for (i = 0; i < longJobs.length; i++) partSpans.push(longJobs[i].parts[0], longJobs[i].parts[1]);
    var partRanges = await findRanges(context, caps, paragraph, text, partSpans, true);
    for (i = 0; i < longJobs.length; i++) {
      var head = partRanges[2 * i];
      var tail = partRanges[2 * i + 1];
      if (head && tail && caps.api13) results[longJobs[i].i] = head.expandTo(tail);
      else if (head) results[longJobs[i].i] = head;
    }
  }

  // Phase 1: search for each (unique) window in the paragraph.
  var outer = {};
  var any = false;
  for (i = 0; i < jobs.length; i++) {
    if (jobs[i].long) continue;
    if (!outer[jobs[i].winText]) {
      var coll = paragraph.search(escapeWordSearch(jobs[i].winText), { matchCase: true });
      coll.load('items/text');
      outer[jobs[i].winText] = coll;
      any = true;
    }
  }
  if (!any) return results;
  await context.sync();

  // Phase 2: narrow each window to the exact span.
  var needSync = false;
  for (i = 0; i < jobs.length; i++) {
    var job = jobs[i];
    if (job.long) continue;
    var cand = outer[job.winText].items[job.win.occurrence];
    if (!cand) continue;
    job.cand = cand;
    if (job.win.start === job.start && job.win.end === job.end) {
      job.range = cand;
      continue;
    }
    var rel = job.start - job.win.start;
    // Extra-space fixes are anchored between their neighbouring words when WordApi 1.3 is
    // available; older Word searches for the spaces themselves.
    if (!isBlank(job.target) || !caps.api13) {
      var occ = occurrenceIndex(job.winText, job.target, rel);
      if (occ !== -1) {
        job.inner = cand.search(escapeWordSearch(job.target), { matchCase: true });
        job.inner.load('items/text');
        job.innerOcc = occ;
        needSync = true;
        continue;
      }
    }
    if (caps.api13) {
      // Anchor between the text before and after the span (handles extra spaces).
      var leftText = job.winText.slice(0, rel);
      var rightText = job.winText.slice(rel + job.target.length);
      if (leftText && !isBlank(leftText)) {
        job.left = cand.search(escapeWordSearch(leftText), { matchCase: true });
        job.left.load('items/text');
      }
      if (rightText && !isBlank(rightText)) {
        job.right = cand.search(escapeWordSearch(rightText), { matchCase: true });
        job.right.load('items/text');
        job.rightOcc = occurrenceIndex(job.winText, rightText, rel + job.target.length);
      }
      job.anchored = true;
      needSync = true;
    }
  }
  if (needSync) await context.sync();

  // Phase 3: build anchored ranges and verify everything.
  var verify = [];
  for (i = 0; i < jobs.length; i++) {
    var jb = jobs[i];
    if (jb.long) continue;
    if (jb.inner) {
      jb.range = jb.inner.items[jb.innerOcc] || null;
    } else if (jb.anchored && jb.cand) {
      var startPoint = jb.left && jb.left.items[0] ? jb.left.items[0].getRange('End') : jb.cand.getRange('Start');
      var endPoint = jb.right && jb.right.items[jb.rightOcc] ? jb.right.items[jb.rightOcc].getRange('Start') : jb.cand.getRange('End');
      jb.range = startPoint.expandTo(endPoint);
      jb.range.load('text');
      verify.push(jb);
    }
  }
  if (verify.length) await context.sync();
  for (i = 0; i < jobs.length; i++) {
    var jj = jobs[i];
    if (jj.long || !jj.range) continue;
    if (norm(jj.range.text) === norm(jj.target)) results[jj.i] = jj.range;
  }
  return results;
}

async function loadParagraphs(context, self) {
  var paras = context.document.body.paragraphs;
  paras.load(self.paragraphFields());
  await context.sync();
  return paras.items;
}

// Select the span in the document. Returns 'ok', 'paragraph' (fell back to the paragraph) or 'gone'.
WordAdapter.prototype.locate = function (ref, start, end) {
  var self = this;
  var caps = this.caps;
  return Word.run(async function (context) {
    var items = await loadParagraphs(context, self);
    var hit = findParagraph(items, caps, ref);
    if (!hit) return 'gone';
    var text = hit.p.text;
    var s = start;
    var e = end;
    if (text !== ref.text) {
      var original = ref.text.slice(start, end);
      var pos = text.indexOf(original, Math.max(0, start - 40));
      if (pos === -1) pos = text.indexOf(original);
      if (pos === -1 || !original) {
        hit.p.select();
        await context.sync();
        return 'paragraph';
      }
      s = pos;
      e = pos + original.length;
    }
    var ranges = await findRanges(context, caps, hit.p, text, [{ start: s, end: e }]);
    if (ranges[0]) {
      ranges[0].select();
      await context.sync();
      return 'ok';
    }
    hit.p.select();
    await context.sync();
    return 'paragraph';
  });
};

// Apply replacements. fixes: [{ref, start, end, replacement, id}] (any paragraphs).
// Resolves to [{key, index, status, oldText, newText, applied: [{id, start, end, replacement}]}]
WordAdapter.prototype.applyFixes = function (fixes) {
  var self = this;
  var caps = this.caps;
  return Word.run(async function (context) {
    var items = await loadParagraphs(context, self);
    var groups = [];
    var byKey = {};
    for (var i = 0; i < fixes.length; i++) {
      var f = fixes[i];
      var g = byKey[f.ref.key];
      if (!g) {
        g = { ref: f.ref, fixes: [] };
        byKey[f.ref.key] = g;
        groups.push(g);
      }
      g.fixes.push(f);
    }
    var report = [];
    var touched = [];
    for (var gi = 0; gi < groups.length; gi++) {
      var grp = groups[gi];
      var hit = findParagraph(items, caps, grp.ref);
      var entry = { key: grp.ref.key, index: grp.ref.index, oldText: grp.ref.text, applied: [], status: 'ok' };
      report.push(entry);
      if (!hit) {
        entry.status = 'gone';
        continue;
      }
      if (hit.p.text !== grp.ref.text) {
        entry.status = 'stale';
        entry.newText = hit.p.text;
        continue;
      }
      var chosen = pickNonOverlapping(grp.fixes);
      var ranges = await findRanges(context, caps, hit.p, hit.p.text, chosen);
      for (var r = 0; r < chosen.length; r++) {
        if (!ranges[r]) continue;
        ranges[r].insertText(chosen[r].replacement, 'Replace');
        entry.applied.push({ id: chosen[r].id, start: chosen[r].start, end: chosen[r].end, replacement: chosen[r].replacement });
      }
      if (!entry.applied.length) entry.status = 'notfound';
      hit.p.load('text');
      touched.push({ entry: entry, p: hit.p, index: hit.index });
    }
    await context.sync();
    for (var t = 0; t < touched.length; t++) {
      touched[t].entry.newText = touched[t].p.text;
      touched[t].entry.index = touched[t].index;
    }
    return report;
  });
};

// ---------------------------------------------------------------------------
// In-document underlines (annotations, WordApi 1.7+, Microsoft 365)
// ---------------------------------------------------------------------------

function critiqueFor(issue, caps) {
  var cat = CATEGORIES[issue.category] || CATEGORIES.clarity;
  var critique = {
    colorScheme: issue.source === 'ai' ? 'Berry' : cat.critique,
    start: issue.offset,
    length: Math.max(1, issue.length)
  };
  if (caps.popups) {
    var suggestions = [];
    for (var i = 0; i < issue.replacements.length && suggestions.length < 3; i++) {
      if (issue.replacements[i] && !(issue.labels && issue.labels[i])) suggestions.push(issue.replacements[i]);
    }
    critique.popupOptions = {
      brandingTextResourceId: 'WA.Brand',
      titleResourceId: typeInfo(issue.type).titleRes,
      subtitleResourceId: cat.subtitleRes,
      suggestions: suggestions
    };
  }
  return critique;
}

// entries: [{ref, issues}] -> Promise<{issueId: annotationId}>
WordAdapter.prototype.setAnnotations = function (entries) {
  var self = this;
  var caps = this.caps;
  if (!this.annotationsWorking) return Promise.resolve({});
  return Word.run(async function (context) {
    var items = await loadParagraphs(context, self);
    var targets = [];
    for (var i = 0; i < entries.length; i++) {
      var hit = findParagraph(items, caps, entries[i].ref);
      if (!hit || hit.p.text !== entries[i].ref.text) continue;
      var anns = hit.p.getAnnotations();
      anns.load('items/id');
      targets.push({ p: hit.p, issues: entries[i].issues, anns: anns });
    }
    await context.sync();
    for (var t = 0; t < targets.length; t++) {
      var a = targets[t].anns.items;
      for (var d = 0; d < a.length; d++) a[d].delete();
      var critiques = [];
      var ids = [];
      var len = targets[t].p.text.length;
      for (var k = 0; k < targets[t].issues.length; k++) {
        var is = targets[t].issues[k];
        if (is.offset < 0 || is.offset + Math.max(1, is.length) > len) continue;
        critiques.push(critiqueFor(is, caps));
        ids.push(is.id);
      }
      targets[t].ids = ids;
      if (critiques.length) targets[t].result = targets[t].p.insertAnnotations({ critiques: critiques });
    }
    await context.sync();
    var map = {};
    for (var m = 0; m < targets.length; m++) {
      if (!targets[m].result) continue;
      var vals = targets[m].result.value || [];
      for (var v = 0; v < vals.length; v++) map[targets[m].ids[v]] = vals[v];
    }
    return map;
  });
};

WordAdapter.prototype.clearAnnotations = function () {
  if (!this.caps.annotations) return Promise.resolve();
  return Word.run(async function (context) {
    var paras = context.document.body.paragraphs;
    paras.load('items');
    await context.sync();
    var lists = [];
    for (var i = 0; i < paras.items.length; i++) {
      var anns = paras.items[i].getAnnotations();
      anns.load('items/id');
      lists.push(anns);
    }
    await context.sync();
    for (var j = 0; j < lists.length; j++) {
      for (var k = 0; k < lists[j].items.length; k++) lists[j].items[k].delete();
    }
    await context.sync();
  });
};

WordAdapter.prototype.deleteAnnotation = function (annotationId) {
  if (!this.annotationsWorking || !annotationId) return Promise.resolve();
  return Word.run(async function (context) {
    context.document.getAnnotationById(annotationId).delete();
    await context.sync();
  }).then(null, function () {
    /* already gone */
  });
};

// ---------------------------------------------------------------------------
// Events
// ---------------------------------------------------------------------------

// handlers: {onChange(), onAnnotationClick(annotationId), onAnnotationAction({annotationId, action, suggestion})}
WordAdapter.prototype.watch = function (handlers) {
  var caps = this.caps;
  var self = this;
  function selectionFallback() {
    try {
      Office.context.document.addHandlerAsync(Office.EventType.DocumentSelectionChanged, function () {
        handlers.onChange('selection');
      });
      self.watchMode = 'selection';
    } catch (e) {
      self.watchMode = 'none';
    }
  }
  var changeEvents = caps.api16
    ? Word.run(async function (context) {
        var doc = context.document;
        var fire = function () {
          handlers.onChange('paragraph');
          return Promise.resolve();
        };
        doc.onParagraphChanged.add(fire);
        doc.onParagraphAdded.add(fire);
        doc.onParagraphDeleted.add(fire);
        await context.sync();
        self.watchMode = 'paragraph';
      }).then(null, selectionFallback)
    : Promise.resolve(selectionFallback());

  return changeEvents.then(function () {
    if (!caps.annotations) return null;
    return Word.run(async function (context) {
      context.document.onAnnotationClicked.add(function (args) {
        handlers.onAnnotationClick(args.id);
        return Promise.resolve();
      });
      if (caps.popups) {
        context.document.onAnnotationPopupAction.add(function (args) {
          handlers.onAnnotationAction({ annotationId: args.id, action: args.action, suggestion: args.critiqueSuggestion });
          return Promise.resolve();
        });
      }
      await context.sync();
    }).then(null, function () {
      /* annotation events unavailable */
    });
  });
};

// ---------------------------------------------------------------------------
// Selection helpers for AI rewriting
// ---------------------------------------------------------------------------

WordAdapter.prototype.getSelectionText = function () {
  return Word.run(async function (context) {
    var sel = context.document.getSelection();
    sel.load('text');
    await context.sync();
    return (sel.text || '').replace(/\r/g, '\n');
  });
};

// Replace the current selection if it still holds `originalText`.
// Resolves to 'ok' or 'moved' (the selection no longer matches).
WordAdapter.prototype.replaceSelection = function (originalText, newText) {
  return Word.run(async function (context) {
    var sel = context.document.getSelection();
    sel.load('text');
    await context.sync();
    if (norm(sel.text).replace(/^\s+|\s+$/g, '') === norm(originalText).replace(/^\s+|\s+$/g, '')) {
      sel.insertText(newText, 'Replace');
      await context.sync();
      return 'ok';
    }
    // The user clicked elsewhere: find the original text if it is unique and short enough.
    if (isSearchable(originalText)) {
      var found = context.document.body.search(escapeWordSearch(originalText), { matchCase: true });
      found.load('items');
      await context.sync();
      if (found.items.length === 1) {
        found.items[0].insertText(newText, 'Replace');
        found.items[0].select();
        await context.sync();
        return 'ok';
      }
    }
    return 'moved';
  });
};

WordAdapter.prototype.insertAfterSelection = function (newText) {
  return Word.run(async function (context) {
    var paras = context.document.getSelection().paragraphs;
    paras.load('items');
    await context.sync();
    if (!paras.items.length) return 'moved';
    var anchor = paras.items[paras.items.length - 1];
    var lines = newText.split(/\n+/);
    for (var i = 0; i < lines.length; i++) {
      anchor = anchor.insertParagraph(lines[i], 'After');
    }
    anchor.select('End');
    await context.sync();
    return 'ok';
  });
};

// ---------------------------------------------------------------------------
// Review comments (WordApi 1.4)
// ---------------------------------------------------------------------------

export var COMMENT_PREFIX = 'WriteAssist:';

// items: [{ref, start, end, text}] -> Promise<number of comments added>
WordAdapter.prototype.insertComments = function (items) {
  var self = this;
  var caps = this.caps;
  if (!caps.comments) return Promise.reject(new Error('Comments need Word 2021, Microsoft 365 or Word on the web.'));
  return Word.run(async function (context) {
    var paras = await loadParagraphs(context, self);
    var groups = {};
    var order = [];
    for (var i = 0; i < items.length; i++) {
      var k = items[i].ref.key;
      if (!groups[k]) {
        groups[k] = [];
        order.push(k);
      }
      groups[k].push(items[i]);
    }
    var added = 0;
    for (var g = 0; g < order.length; g++) {
      var list = groups[order[g]];
      var hit = findParagraph(paras, caps, list[0].ref);
      if (!hit || hit.p.text !== list[0].ref.text) continue;
      var ranges = await findRanges(context, caps, hit.p, hit.p.text, list);
      for (var r = 0; r < list.length; r++) {
        if (!ranges[r]) continue;
        ranges[r].insertComment(COMMENT_PREFIX + ' ' + list[r].text);
        added++;
      }
    }
    await context.sync();
    return added;
  });
};

WordAdapter.prototype.removeComments = function () {
  if (!this.caps.comments) return Promise.resolve(0);
  return Word.run(async function (context) {
    var comments = context.document.body.getComments();
    comments.load('items/content');
    await context.sync();
    var n = 0;
    for (var i = 0; i < comments.items.length; i++) {
      if ((comments.items[i].content || '').indexOf(COMMENT_PREFIX) === 0) {
        comments.items[i].delete();
        n++;
      }
    }
    await context.sync();
    return n;
  });
};

// ---------------------------------------------------------------------------
// Document-level preferences
// ---------------------------------------------------------------------------

WordAdapter.prototype.getAutoOpen = function () {
  try {
    return !!Office.context.document.settings.get('Office.AutoShowTaskpaneWithDocument');
  } catch (e) {
    return false;
  }
};

WordAdapter.prototype.setAutoOpen = function (on) {
  return new Promise(function (resolve, reject) {
    try {
      var s = Office.context.document.settings;
      if (on) s.set('Office.AutoShowTaskpaneWithDocument', true);
      else s.remove('Office.AutoShowTaskpaneWithDocument');
      s.saveAsync(function (res) {
        if (res && res.status === 'failed') reject(new Error('Word could not save the setting.'));
        else resolve();
      });
    } catch (e) {
      reject(e);
    }
  });
};

WordAdapter.prototype.documentId = function () {
  try {
    return Office.context.document.url || '';
  } catch (e) {
    return '';
  }
};

WordAdapter.prototype.isDarkTheme = function () {
  try {
    var theme = Office.context.officeTheme;
    if (!theme) return false;
    if (typeof theme.isDarkTheme === 'boolean') return theme.isDarkTheme;
    var hex = (theme.bodyBackgroundColor || '#ffffff').replace('#', '');
    if (hex.length === 3) hex = hex.charAt(0) + hex.charAt(0) + hex.charAt(1) + hex.charAt(1) + hex.charAt(2) + hex.charAt(2);
    var r = parseInt(hex.slice(0, 2), 16);
    var g = parseInt(hex.slice(2, 4), 16);
    var b = parseInt(hex.slice(4, 6), 16);
    return 0.2126 * r + 0.7152 * g + 0.0722 * b < 128;
  } catch (e) {
    return false;
  }
};
