// A stand-in for Word used by demo.html: a plain-text "document" (textarea) with
// coloured underlines drawn on a backdrop behind it. Same interface as WordAdapter.

import { pickNonOverlapping } from '../core/issues.js';

export function DemoAdapter(textarea, backdrop) {
  this.kind = 'demo';
  this.textarea = textarea;
  this.backdrop = backdrop;
  this.caps = { api13: true, api14: false, api16: false, annotations: true, popups: false, comments: false, documentSettings: false, platform: 'Browser' };
  this.annotationsWorking = true;
  this.marks = {}; // line index -> [{id, start, end, category, source}]
  this.annIndex = {}; // annotationId -> issue id
  this.scroller = document.getElementById('demo-canvas') || textarea.parentNode;
  var self = this;
  this.renderBackdrop();
  this.autosize();
  window.addEventListener('resize', function () {
    self.autosize();
  });
}

// The textarea grows with its content so it never scrolls on its own; the page scrolls
// instead, which keeps the underline layer aligned with the text.
DemoAdapter.prototype.autosize = function () {
  var ta = this.textarea;
  ta.style.height = 'auto';
  ta.style.height = ta.scrollHeight + 'px';
};

DemoAdapter.prototype.lines = function () {
  return this.textarea.value.split('\n');
};

DemoAdapter.prototype.readParagraphs = function (scope) {
  var lines = this.lines();
  var out = [];
  var selStart = this.textarea.selectionStart;
  var selEnd = this.textarea.selectionEnd;
  var pos = 0;
  for (var i = 0; i < lines.length; i++) {
    var lineStart = pos;
    var lineEnd = pos + lines[i].length;
    pos = lineEnd + 1;
    if (scope === 'selection') {
      if (selEnd < lineStart || selStart > lineEnd) continue;
    }
    out.push({ key: 'i' + i, index: i, text: lines[i] });
  }
  return Promise.resolve(out);
};

DemoAdapter.prototype.lineOffset = function (index) {
  var lines = this.lines();
  var off = 0;
  for (var i = 0; i < index && i < lines.length; i++) off += lines[i].length + 1;
  return off;
};

DemoAdapter.prototype.findLine = function (ref) {
  var lines = this.lines();
  if (lines[ref.index] === ref.text) return ref.index;
  var best = -1;
  var bestDist = Infinity;
  for (var i = 0; i < lines.length; i++) {
    if (lines[i] === ref.text && Math.abs(i - ref.index) < bestDist) {
      best = i;
      bestDist = Math.abs(i - ref.index);
    }
  }
  return best;
};

DemoAdapter.prototype.locate = function (ref, start, end) {
  var idx = this.findLine(ref);
  if (idx === -1) return Promise.resolve('gone');
  var base = this.lineOffset(idx);
  var ta = this.textarea;
  try {
    ta.focus({ preventScroll: true });
  } catch (e) {
    ta.focus();
  }
  ta.setSelectionRange(base + start, base + end);
  var line = this.backdrop.querySelector('[data-line="' + idx + '"]');
  var sc = this.scroller;
  if (line && sc) {
    var top = line.offsetTop + ta.offsetTop - sc.clientHeight / 3;
    var pageTop = 0;
    var node = ta.offsetParent;
    while (node && node !== sc && node !== document.body) {
      pageTop += node.offsetTop;
      node = node.offsetParent;
    }
    sc.scrollTop = Math.max(0, top + pageTop);
  }
  return Promise.resolve('ok');
};

DemoAdapter.prototype.applyFixes = function (fixes) {
  var lines = this.lines();
  var report = [];
  var byKey = {};
  var order = [];
  for (var i = 0; i < fixes.length; i++) {
    var k = fixes[i].ref.key;
    if (!byKey[k]) {
      byKey[k] = [];
      order.push(k);
    }
    byKey[k].push(fixes[i]);
  }
  for (var g = 0; g < order.length; g++) {
    var list = byKey[order[g]];
    var ref = list[0].ref;
    var idx = this.findLine(ref);
    var entry = { key: ref.key, index: ref.index, oldText: ref.text, applied: [], status: 'ok' };
    report.push(entry);
    if (idx === -1) {
      entry.status = lines[ref.index] !== undefined ? 'stale' : 'gone';
      entry.newText = lines[ref.index];
      continue;
    }
    var text = lines[idx];
    var sorted = pickNonOverlapping(list);
    for (var s = 0; s < sorted.length; s++) {
      var f = sorted[s];
      text = text.slice(0, f.start) + f.replacement + text.slice(f.end);
      entry.applied.push({ id: f.id, start: f.start, end: f.end, replacement: f.replacement });
    }
    lines[idx] = text;
    entry.newText = text;
    entry.index = idx;
    delete this.marks[idx];
  }
  this.setValue(lines.join('\n'));
  return Promise.resolve(report);
};

DemoAdapter.prototype.setValue = function (value) {
  this.textarea.value = value;
  this.renderBackdrop();
  this.autosize();
  if (this.onChangeHandler) this.onChangeHandler('paragraph');
};

DemoAdapter.prototype.setAnnotations = function (entries) {
  var map = {};
  for (var i = 0; i < entries.length; i++) {
    var idx = this.findLine(entries[i].ref);
    if (idx === -1) continue;
    var list = [];
    for (var k = 0; k < entries[i].issues.length; k++) {
      var is = entries[i].issues[k];
      var annId = 'demo-' + is.id;
      map[is.id] = annId;
      this.annIndex[annId] = is.id;
      list.push({ id: annId, start: is.offset, end: is.offset + Math.max(1, is.length), category: is.category, source: is.source, sentenceLevel: is.sentenceLevel });
    }
    this.marks[idx] = list;
  }
  this.renderBackdrop();
  return Promise.resolve(map);
};

DemoAdapter.prototype.clearAnnotations = function () {
  this.marks = {};
  this.renderBackdrop();
  return Promise.resolve();
};

DemoAdapter.prototype.deleteAnnotation = function (annotationId) {
  for (var line in this.marks) {
    if (!Object.prototype.hasOwnProperty.call(this.marks, line)) continue;
    var list = this.marks[line];
    for (var i = 0; i < list.length; i++) {
      if (list[i].id === annotationId) {
        list.splice(i, 1);
        this.renderBackdrop();
        return Promise.resolve();
      }
    }
  }
  return Promise.resolve();
};

DemoAdapter.prototype.renderBackdrop = function () {
  var lines = this.lines();
  var bd = this.backdrop;
  while (bd.firstChild) bd.removeChild(bd.firstChild);
  for (var i = 0; i < lines.length; i++) {
    var line = document.createElement('div');
    line.className = 'demo-line';
    line.setAttribute('data-line', String(i));
    var text = lines[i];
    var marks = (this.marks[i] || []).filter(function (m) {
      return !m.sentenceLevel;
    }).sort(function (a, b) {
      return a.start - b.start;
    });
    var pos = 0;
    for (var m = 0; m < marks.length; m++) {
      var mk = marks[m];
      if (mk.start < pos || mk.end > text.length) continue;
      if (mk.start > pos) line.appendChild(document.createTextNode(text.slice(pos, mk.start)));
      var span = document.createElement('span');
      span.className = 'demo-mark demo-' + (mk.source === 'ai' ? 'ai' : mk.category);
      span.textContent = text.slice(mk.start, mk.end);
      line.appendChild(span);
      pos = mk.end;
    }
    line.appendChild(document.createTextNode(text.slice(pos) + (i === lines.length - 1 ? '\n' : '')));
    if (!text) line.appendChild(document.createTextNode('\u200b'));
    bd.appendChild(line);
  }
};

DemoAdapter.prototype.watch = function (handlers) {
  var self = this;
  this.onChangeHandler = handlers.onChange;
  this.watchMode = 'paragraph';
  this.textarea.addEventListener('input', function () {
    // underlines are stale while typing; the live re-check redraws them a moment later
    self.marks = {};
    self.renderBackdrop();
    self.autosize();
    handlers.onChange('paragraph');
  });
  this.textarea.addEventListener('click', function () {
    var caret = self.textarea.selectionStart;
    var lines = self.lines();
    var pos = 0;
    for (var i = 0; i < lines.length; i++) {
      if (caret <= pos + lines[i].length) {
        var col = caret - pos;
        var list = self.marks[i] || [];
        for (var k = 0; k < list.length; k++) {
          if (!list[k].sentenceLevel && col >= list[k].start && col <= list[k].end) {
            handlers.onAnnotationClick(list[k].id);
            return;
          }
        }
        return;
      }
      pos += lines[i].length + 1;
    }
  });
  return Promise.resolve();
};

DemoAdapter.prototype.getSelectionText = function () {
  var ta = this.textarea;
  return Promise.resolve(ta.value.slice(ta.selectionStart, ta.selectionEnd));
};

DemoAdapter.prototype.replaceSelection = function (originalText, newText) {
  var ta = this.textarea;
  var cur = ta.value.slice(ta.selectionStart, ta.selectionEnd);
  var start;
  if (cur === originalText) {
    start = ta.selectionStart;
  } else {
    start = ta.value.indexOf(originalText);
    if (start === -1 || ta.value.indexOf(originalText, start + 1) !== -1) return Promise.resolve('moved');
  }
  var end = start + originalText.length;
  this.marks = {};
  this.setValue(ta.value.slice(0, start) + newText + ta.value.slice(end));
  ta.setSelectionRange(start, start + newText.length);
  return Promise.resolve('ok');
};

DemoAdapter.prototype.insertAfterSelection = function (newText) {
  var ta = this.textarea;
  var end = ta.value.indexOf('\n', ta.selectionEnd);
  if (end === -1) end = ta.value.length;
  this.setValue(ta.value.slice(0, end) + '\n' + newText + ta.value.slice(end));
  return Promise.resolve('ok');
};

DemoAdapter.prototype.insertComments = function () {
  return Promise.reject(new Error('Comments are available when WriteAssist runs inside Word.'));
};

DemoAdapter.prototype.removeComments = function () {
  return Promise.resolve(0);
};

DemoAdapter.prototype.getAutoOpen = function () {
  return false;
};

DemoAdapter.prototype.setAutoOpen = function () {
  return Promise.reject(new Error('Available inside Word.'));
};

DemoAdapter.prototype.documentId = function () {
  return 'demo';
};

DemoAdapter.prototype.isDarkTheme = function () {
  try {
    return !!(window.matchMedia && window.matchMedia('(prefers-color-scheme: dark)').matches);
  } catch (e) {
    return false;
  }
};
