// Minimal XMLHttpRequest wrapper. XHR (rather than fetch) works in every Office webview,
// including the Internet Explorer 11 control used by Office 2016/2019 volume licences.

export function httpRequest(opts) {
  return new Promise(function (resolve, reject) {
    var xhr = new XMLHttpRequest();
    xhr.open(opts.method || 'GET', opts.url, true);
    var headers = opts.headers || {};
    for (var k in headers) {
      if (Object.prototype.hasOwnProperty.call(headers, k)) xhr.setRequestHeader(k, headers[k]);
    }
    try {
      xhr.timeout = opts.timeout || 30000;
    } catch (e) {
      /* some old webviews throw when timeout is set on a sync request; ours is async */
    }
    xhr.onload = function () {
      resolve({ status: xhr.status === 1223 ? 204 : xhr.status, text: xhr.responseText });
    };
    xhr.onerror = function () {
      var err = new Error('Network error');
      err.network = true;
      reject(err);
    };
    xhr.ontimeout = function () {
      var err = new Error('The request timed out');
      err.timeout = true;
      err.network = true;
      reject(err);
    };
    if (opts.onCreate) opts.onCreate(xhr);
    xhr.send(opts.body === undefined ? null : opts.body);
  });
}

export function formEncode(obj) {
  var parts = [];
  for (var k in obj) {
    if (!Object.prototype.hasOwnProperty.call(obj, k)) continue;
    var v = obj[k];
    if (v === undefined || v === null || v === '') continue;
    parts.push(encodeURIComponent(k) + '=' + encodeURIComponent(String(v)));
  }
  return parts.join('&');
}

export function parseJSON(text) {
  try {
    return JSON.parse(text);
  } catch (e) {
    return null;
  }
}
