// Tiny DOM helpers that work in Internet Explorer 11 as well as modern webviews.

export function h(tag, props) {
  var el = document.createElement(tag);
  if (props) {
    for (var k in props) {
      if (!Object.prototype.hasOwnProperty.call(props, k)) continue;
      var v = props[k];
      if (v === undefined || v === null || v === false) continue;
      if (k === 'className') el.className = v;
      else if (k === 'text') el.appendChild(document.createTextNode(String(v)));
      else if (k === 'html') el.innerHTML = v; // trusted, static markup only (icons)
      else if (k === 'on') {
        for (var ev in v) if (Object.prototype.hasOwnProperty.call(v, ev)) el.addEventListener(ev, v[ev]);
      } else if (k === 'value') el.value = v;
      else if (k === 'checked') el.checked = !!v;
      else if (k === 'disabled') el.disabled = !!v;
      else if (k === 'selected') el.selected = !!v;
      else if (v === true) el.setAttribute(k, '');
      else el.setAttribute(k, String(v));
    }
  }
  for (var i = 2; i < arguments.length; i++) appendOne(el, arguments[i]);
  return el;
}

// append(el, child1, child2, ...): strings become text nodes, arrays are flattened and
// null / undefined / false are skipped.
export function append(el) {
  for (var i = 1; i < arguments.length; i++) appendOne(el, arguments[i]);
  return el;
}

function appendOne(el, child) {
  if (child === null || child === undefined || child === false) return;
  if (child instanceof Array) {
    for (var i = 0; i < child.length; i++) appendOne(el, child[i]);
  } else if (typeof child === 'string' || typeof child === 'number') {
    el.appendChild(document.createTextNode(String(child)));
  } else {
    el.appendChild(child);
  }
}

export function clear(el) {
  while (el.firstChild) el.removeChild(el.firstChild);
  return el;
}

export function replaceChildren(el) {
  clear(el);
  for (var i = 1; i < arguments.length; i++) appendOne(el, arguments[i]);
  return el;
}

export function closest(el, selector) {
  var node = el;
  while (node && node.nodeType === 1) {
    if (matches(node, selector)) return node;
    node = node.parentNode;
  }
  return null;
}

export function matches(el, selector) {
  var fn = el.matches || el.msMatchesSelector || el.webkitMatchesSelector;
  return fn ? fn.call(el, selector) : false;
}

export function toggleClass(el, cls, on) {
  if (!el) return;
  if (on) el.classList.add(cls);
  else el.classList.remove(cls);
}

export function qs(root, selector) {
  return root.querySelector(selector);
}

export function qsa(root, selector) {
  return Array.prototype.slice.call(root.querySelectorAll(selector));
}

export function copyText(text) {
  return new Promise(function (resolve, reject) {
    function fallback() {
      var ta = document.createElement('textarea');
      ta.value = text;
      ta.setAttribute('readonly', '');
      ta.style.position = 'fixed';
      ta.style.top = '-1000px';
      document.body.appendChild(ta);
      ta.select();
      var ok = false;
      try {
        ok = document.execCommand('copy');
      } catch (e) {
        ok = false;
      }
      document.body.removeChild(ta);
      if (ok) resolve();
      else reject(new Error('Copy is blocked here. Select the text and press Ctrl+C.'));
    }
    try {
      if (navigator.clipboard && navigator.clipboard.writeText) {
        navigator.clipboard.writeText(text).then(resolve, fallback);
        return;
      }
    } catch (e) {
      /* fall through */
    }
    fallback();
  });
}

export function prefersReducedMotion() {
  try {
    return !!(window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches);
  } catch (e) {
    return false;
  }
}
