// Small, dependency-free helpers. Everything here must transpile cleanly to ES5
// (the add-in also runs inside the Internet Explorer 11 webview used by older Office).

var uidCounter = 0;
export function uid(prefix) {
  uidCounter += 1;
  return (prefix || 'id') + '-' + uidCounter.toString(36) + '-' + Math.floor(Math.random() * 1e6).toString(36);
}

export function clamp(value, min, max) {
  return Math.max(min, Math.min(max, value));
}

export function debounce(fn, wait) {
  var timer = null;
  function debounced() {
    var args = arguments;
    var self = this;
    if (timer) clearTimeout(timer);
    timer = setTimeout(function () {
      timer = null;
      fn.apply(self, args);
    }, wait);
  }
  debounced.cancel = function () {
    if (timer) clearTimeout(timer);
    timer = null;
  };
  debounced.setWait = function (ms) {
    wait = ms;
  };
  return debounced;
}

export function delay(ms) {
  return new Promise(function (resolve) {
    setTimeout(resolve, ms);
  });
}

export function escapeRegExp(s) {
  return String(s).replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

// Make `replacement` follow the capitalisation of `original`
// ("In order to" -> "To", "IN ORDER TO" -> "TO").
export function matchCase(original, replacement) {
  if (!replacement) return replacement;
  if (original.length > 1 && original === original.toUpperCase() && /[A-Z]/.test(original)) {
    return replacement.toUpperCase();
  }
  var first = original.charAt(0);
  if (first && first === first.toUpperCase() && first !== first.toLowerCase()) {
    return replacement.charAt(0).toUpperCase() + replacement.slice(1);
  }
  return replacement;
}

export function formatNumber(n) {
  var s = String(Math.round(n));
  var out = '';
  var neg = s.charAt(0) === '-';
  if (neg) s = s.slice(1);
  while (s.length > 3) {
    out = ',' + s.slice(-3) + out;
    s = s.slice(0, -3);
  }
  return (neg ? '-' : '') + s + out;
}

export function formatDuration(minutes) {
  var totalSeconds = Math.round(minutes * 60);
  if (totalSeconds < 60) return totalSeconds + ' sec';
  var m = Math.floor(totalSeconds / 60);
  var s = totalSeconds % 60;
  if (m >= 60) {
    var h = Math.floor(m / 60);
    return h + ' hr ' + (m % 60) + ' min';
  }
  return s ? m + ' min ' + s + ' sec' : m + ' min';
}

export function plural(n, one, many) {
  return n === 1 ? one : (many || one + 's');
}

export function hashString(str) {
  // FNV-1a 32-bit, returned as base36 together with the length to make collisions negligible.
  var h = 0x811c9dc5;
  for (var i = 0; i < str.length; i++) {
    h ^= str.charCodeAt(i);
    h = (h + ((h << 1) + (h << 4) + (h << 7) + (h << 8) + (h << 24))) >>> 0;
  }
  return h.toString(36) + '.' + str.length.toString(36);
}

export function assign(target) {
  for (var i = 1; i < arguments.length; i++) {
    var src = arguments[i];
    if (!src) continue;
    for (var k in src) {
      if (Object.prototype.hasOwnProperty.call(src, k)) target[k] = src[k];
    }
  }
  return target;
}

export function deepClone(obj) {
  return JSON.parse(JSON.stringify(obj));
}

export function storageGet(key, fallback) {
  try {
    var raw = window.localStorage.getItem(key);
    if (raw == null) return fallback;
    return JSON.parse(raw);
  } catch (e) {
    return fallback;
  }
}

export function storageSet(key, value) {
  try {
    window.localStorage.setItem(key, JSON.stringify(value));
    return true;
  } catch (e) {
    return false;
  }
}

export function storageRemove(key) {
  try {
    window.localStorage.removeItem(key);
  } catch (e) {
    /* ignore */
  }
}

export function errorMessage(err) {
  if (!err) return 'Unknown error';
  if (typeof err === 'string') return err;
  if (err.message) return err.message;
  try {
    return JSON.stringify(err);
  } catch (e) {
    return String(err);
  }
}
