// Text utilities: sentence splitting, tokenising, readability helpers and the
// search helpers used to map character offsets onto Word ranges.

var ABBREVIATIONS = [
  'mr', 'mrs', 'ms', 'dr', 'prof', 'sr', 'jr', 'st', 'no', 'nos', 'vs', 'v', 'fig', 'figs', 'eq', 'eqs',
  'approx', 'govt', 'pvt', 'ltd', 'inc', 'dept', 'rs', 'nrs', 'hon', 'ref', 'refs', 'vol', 'vols', 'pp',
  'p', 'cf', 'al', 'resp', 'jan', 'feb', 'mar', 'apr', 'jun', 'jul', 'aug', 'sep', 'sept', 'oct', 'nov', 'dec'
];
var ABBR_SET = {};
for (var a = 0; a < ABBREVIATIONS.length; a++) ABBR_SET[ABBREVIATIONS[a]] = true;

var WORD_RE = /[A-Za-z\u00c0-\u024f0-9]+(?:[.,][0-9]+)*(?:['\u2019\-][A-Za-z\u00c0-\u024f0-9]+)*/g;
var LETTER_RE = /[A-Za-z\u00c0-\u024f]/;

function isSpace(ch) {
  return ch === ' ' || ch === '\t' || ch === '\u00a0' || ch === '\u000b' || ch === '\n' || ch === '\r';
}

// Split a paragraph into sentences. Returns [{start, end, text}] with `end` exclusive and
// trailing whitespace trimmed. Handles common abbreviations, initials and decimals.
export function splitSentences(text) {
  var out = [];
  var len = text.length;
  var start = 0;
  // skip leading whitespace
  while (start < len && isSpace(text.charAt(start))) start++;
  var i = start;
  while (i < len) {
    var ch = text.charAt(i);
    var boundary = false;
    var cut = i + 1;
    if (ch === '\u000b' || ch === '\n' || ch === '\r') {
      boundary = true;
      cut = i;
    } else if (ch === '.' || ch === '!' || ch === '?') {
      // consume runs like "?!" or "..." and closing quotes/brackets
      var j = i + 1;
      while (j < len && (text.charAt(j) === '.' || text.charAt(j) === '!' || text.charAt(j) === '?')) j++;
      while (j < len && /["'\u201d\u2019)\]]/.test(text.charAt(j))) j++;
      if (j >= len || isSpace(text.charAt(j))) {
        boundary = true;
        cut = j;
        var next = nextNonSpace(text, j);
        var nextIsLower = !!next && next.toLowerCase() === next && next.toUpperCase() !== next;
        if (nextIsLower) {
          // a lowercase continuation ("etc.) are", "e.g. roads", '"Why?" he asked') is not a new sentence
          boundary = false;
        } else if (ch === '.' && text.charAt(i + 1) !== '.' && next) {
          // look at the word in front of a single period
          var k = i - 1;
          while (k >= 0 && /[A-Za-z]/.test(text.charAt(k))) k--;
          var word = text.slice(k + 1, i);
          var prevChar = k >= 0 ? text.charAt(k) : ' ';
          var lower = word.toLowerCase();
          if (word.length === 1 && /[A-Z]/.test(word) && (prevChar === ' ' || prevChar === '.' || prevChar === '(' || k < 0)) {
            boundary = false; // an initial, as in "J. Smith"
          } else if (prevChar === '.' && word.length <= 2) {
            boundary = false; // "e.g." / "i.e." / "U.K." style abbreviations
          } else if (ABBR_SET[lower] && lower !== 'etc') {
            boundary = false; // "Mr. Sharma", "Rs. 5,000", "Fig. 3"
          }
        }
      }
      if (!boundary) i = j - 1;
    }
    if (boundary) {
      pushSentence(out, text, start, cut);
      start = cut;
      while (start < len && isSpace(text.charAt(start))) start++;
      i = start;
      continue;
    }
    i++;
  }
  if (start < len) pushSentence(out, text, start, len);
  return out;
}

function nextNonSpace(text, from) {
  for (var i = from; i < text.length; i++) {
    var c = text.charAt(i);
    if (!isSpace(c)) return c;
  }
  return '';
}

function pushSentence(out, text, start, end) {
  var e = end;
  while (e > start && isSpace(text.charAt(e - 1))) e--;
  if (e > start) out.push({ start: start, end: e, text: text.slice(start, e) });
}

export function tokenizeWords(text) {
  var words = [];
  var m;
  WORD_RE.lastIndex = 0;
  while ((m = WORD_RE.exec(text))) {
    words.push({ word: m[0], start: m.index, end: m.index + m[0].length });
  }
  return words;
}

export function countWords(text) {
  var n = 0;
  WORD_RE.lastIndex = 0;
  while (WORD_RE.exec(text)) n++;
  return n;
}

export function syllableCount(word) {
  var w = word.toLowerCase().replace(/[^a-z]/g, '');
  if (!w) return 0;
  if (w.length <= 3) return 1;
  w = w.replace(/(?:[^laeiouy]es|ed|[^laeiouy]e)$/, '').replace(/^y/, '');
  var m = w.match(/[aeiouy]{1,2}/g);
  return m ? m.length : 1;
}

// Share of letters that are Devanagari (Nepali/Hindi). Used to skip paragraphs
// that an English checker cannot help with.
export function devanagariRatio(text) {
  var dev = 0;
  var latin = 0;
  for (var i = 0; i < text.length; i++) {
    var c = text.charCodeAt(i);
    if (c >= 0x0900 && c <= 0x097f) dev++;
    else if ((c >= 65 && c <= 90) || (c >= 97 && c <= 122)) latin++;
  }
  if (dev + latin === 0) return 0;
  return dev / (dev + latin);
}

var NON_LATIN_RE = /[\u0370-\u03ff\u0400-\u04ff\u0590-\u05ff\u0600-\u06ff\u0900-\u0dff\u0e00-\u0eff\u1000-\u109f\u3040-\u30ff\u3400-\u9fff\uac00-\ud7af]/;
export function hasNonLatinScript(text) {
  return NON_LATIN_RE.test(text);
}

export function isCheckable(text) {
  if (!text) return false;
  if (!LETTER_RE.test(text)) return false;
  return devanagariRatio(text) < 0.35;
}

// ---------------------------------------------------------------------------
// Word search helpers
// ---------------------------------------------------------------------------

// Word's Find treats a straight quote in the search text as matching curly quotes too,
// so occurrence counting has to normalise the haystack the same way.
function normaliseForNeedle(hay, needle) {
  if (/['"]/.test(needle)) {
    return hay.replace(/[\u2018\u2019\u201a\u201b]/g, "'").replace(/[\u201c\u201d\u201e\u201f]/g, '"');
  }
  return hay;
}

// Positions of non-overlapping, case-sensitive occurrences, scanning left to right
// exactly like Word's search does.
export function searchPositions(hay, needle) {
  var out = [];
  if (!needle) return out;
  var h = normaliseForNeedle(hay, needle);
  var from = 0;
  for (;;) {
    var j = h.indexOf(needle, from);
    if (j === -1) break;
    out.push(j);
    from = j + needle.length;
  }
  return out;
}

export function occurrenceIndex(hay, needle, position) {
  var positions = searchPositions(hay, needle);
  for (var i = 0; i < positions.length; i++) {
    if (positions[i] === position) return i;
  }
  return -1;
}

export function escapeWordSearch(s) {
  return s
    .replace(/\^/g, '^^')
    .replace(/\t/g, '^t')
    .replace(/\u000b/g, '^l')
    .replace(/\u00a0/g, '^s')
    .replace(/\u00ad/g, '^-');
}

export function isSearchable(s) {
  if (!s) return false;
  if (/[\u0000-\u0008\u000a\u000c-\u001f]/.test(s)) return false;
  return escapeWordSearch(s).length <= 255;
}

export function isBlank(s) {
  return /^[\s\u00a0]*$/.test(s);
}

function expandLeft(text, s) {
  if (s <= 0) return s;
  var i = s;
  while (i > 0 && isSpace(text.charAt(i - 1))) i--;
  while (i > 0 && !isSpace(text.charAt(i - 1))) i--;
  return i;
}

function expandRight(text, e) {
  var len = text.length;
  if (e >= len) return e;
  var i = e;
  while (i < len && isSpace(text.charAt(i))) i++;
  while (i < len && !isSpace(text.charAt(i))) i++;
  return i;
}

// Grow [start, end) outwards a word at a time until the window text is unique in the
// paragraph (or as unique as possible within Word's 255 character search limit).
// Returns {start, end, occurrence} where occurrence is the index Word's search will
// report for this window, or null when the span cannot be addressed by search.
export function findSearchWindow(text, start, end) {
  var s = start;
  var e = end;
  // Never start or end a search on whitespace if we can avoid it: Word handles it,
  // but anchoring on words makes the match far more reliable.
  if (isBlank(text.slice(s, e))) {
    s = expandLeft(text, s);
    e = expandRight(text, e);
  }
  var best = null;
  var turn = 0;
  for (var guard = 0; guard < 60; guard++) {
    var win = text.slice(s, e);
    if (!isSearchable(win)) break;
    var positions = searchPositions(text, win);
    var occ = -1;
    for (var i = 0; i < positions.length; i++) {
      if (positions[i] === s) {
        occ = i;
        break;
      }
    }
    if (occ !== -1) {
      best = { start: s, end: e, occurrence: occ, unique: positions.length === 1 };
      if (positions.length === 1) return best;
    }
    var ns = s;
    var ne = e;
    if (turn % 2 === 0) {
      ns = expandLeft(text, s);
      if (ns === s) ne = expandRight(text, e);
    } else {
      ne = expandRight(text, e);
      if (ne === e) ns = expandLeft(text, s);
    }
    turn++;
    if (ns === s && ne === e) break;
    s = ns;
    e = ne;
  }
  return best;
}

export function sentenceAt(text, offset) {
  var sentences = splitSentences(text);
  for (var i = 0; i < sentences.length; i++) {
    if (offset >= sentences[i].start && offset < sentences[i].end + 1) return sentences[i];
  }
  return sentences.length ? sentences[sentences.length - 1] : { start: 0, end: text.length, text: text };
}
