// Orchestrates the three engines (local rules, LanguageTool, Claude) over a list of
// paragraphs. Results are cached per paragraph text, so re-checking an edited document
// only sends the paragraphs that changed.

import { runLocalRules } from './rules.js';
import { buildChunks, mapMatches, CHUNK_CHARS } from './languagetool.js';
import { isCheckable } from './text.js';
import { mergeIssueLists, instantiate, signature, shiftIssues, applyEdit } from './issues.js';
import { ltParams, ltSignature, aiSignature, makeSpellingFilter } from './settings.js';
import { delay } from './util.js';

var AI_CHUNK_CHARS = 8000;

export function Checker(deps) {
  this.lt = deps.lt;
  this.claude = deps.claude;
  this.sleep = deps.sleep || delay;
  this.ltCache = {};
  this.aiCache = {};
  this.generation = 0;
}

Checker.prototype.clearCache = function () {
  this.ltCache = {};
  this.aiCache = {};
};

Checker.prototype.ltKey = function (settings, text) {
  return ltSignature(settings) + '\u0002' + text;
};

Checker.prototype.aiKey = function (settings, text) {
  return aiSignature(settings) + '\u0002' + text;
};

function aiEnabled(settings) {
  return !!(settings.ai && settings.ai.deepCheck && settings.ai.apiKey);
}

Checker.prototype.entryFor = function (para, settings) {
  var checkable = isCheckable(para.text);
  var ltCached = this.ltCache[this.ltKey(settings, para.text)];
  var aiCached = this.aiCache[this.aiKey(settings, para.text)];
  return {
    key: para.key,
    index: para.index,
    text: para.text,
    checkable: checkable,
    local: checkable ? runLocalRules(para.text, settings, settings.disabledRules) : [],
    lt: !checkable || !settings.useLanguageTool ? [] : ltCached || null,
    ai: !checkable || !aiEnabled(settings) ? [] : aiCached || null
  };
};

Checker.prototype.cancel = function () {
  this.generation++;
};

// hooks: { onUpdate(entries), onProgress(info) }. Resolves to {ltError, aiError, cancelled}.
Checker.prototype.run = function (paragraphs, settings, hooks) {
  var self = this;
  var gen = ++this.generation;
  var status = { ltError: null, aiError: null, cancelled: false };
  function cancelled() {
    return gen !== self.generation;
  }
  var entries = [];
  for (var i = 0; i < paragraphs.length; i++) entries.push(this.entryFor(paragraphs[i], settings));
  hooks.onUpdate(entries);

  function pendingTexts(field) {
    var seen = {};
    var list = [];
    for (var i = 0; i < entries.length; i++) {
      var e = entries[i];
      if (e.checkable && e[field] === null && !seen[e.text]) {
        seen[e.text] = true;
        list.push(e.text);
      }
    }
    return list;
  }

  function refresh(field, cache, keyFn) {
    for (var i = 0; i < entries.length; i++) {
      var e = entries[i];
      if (e.checkable && e[field] === null) e[field] = cache[keyFn(settings, e.text)] || null;
    }
  }

  var ltPhase = function () {
    if (!settings.useLanguageTool) return Promise.resolve();
    var texts = pendingTexts('lt');
    if (!texts.length) return Promise.resolve();
    var params = ltParams(settings);
    var paras = [];
    var textsById = {};
    for (var t = 0; t < texts.length; t++) {
      paras.push({ id: 't' + t, text: texts[t] });
      textsById['t' + t] = texts[t];
    }
    var chunks = buildChunks(paras, CHUNK_CHARS);
    var c = 0;
    function next() {
      if (cancelled()) {
        status.cancelled = true;
        return Promise.resolve();
      }
      if (c >= chunks.length) return Promise.resolve();
      hooks.onProgress({ phase: 'grammar', done: c, total: chunks.length });
      var chunk = chunks[c];
      return self.checkChunk(chunk, params, hooks, 0).then(function (matches) {
        var mapped = mapMatches(chunk, matches, textsById);
        for (var id in mapped) {
          if (Object.prototype.hasOwnProperty.call(mapped, id)) self.ltCache[self.ltKey(settings, textsById[id])] = mapped[id];
        }
        c++;
        refresh('lt', self.ltCache, self.ltKey.bind(self));
        if (!cancelled()) hooks.onUpdate(entries);
        return next();
      }, function (err) {
        status.ltError = err;
        c++;
        // stop on connection or credential problems; carry on after one-off failures
        if (err && (err.network || err.status === 401 || err.status === 403)) return Promise.resolve();
        return next();
      });
    }
    return next();
  };

  var aiPhase = function () {
    if (!aiEnabled(settings) || cancelled()) return Promise.resolve();
    var texts = pendingTexts('ai');
    if (!texts.length) return Promise.resolve();
    var groups = [];
    var cur = [];
    var size = 0;
    for (var t = 0; t < texts.length; t++) {
      if (size + texts[t].length > AI_CHUNK_CHARS && cur.length) {
        groups.push(cur);
        cur = [];
        size = 0;
      }
      cur.push({ id: 'a' + t, text: texts[t] });
      size += texts[t].length;
    }
    if (cur.length) groups.push(cur);
    var g = 0;
    function next() {
      if (cancelled()) {
        status.cancelled = true;
        return Promise.resolve();
      }
      if (g >= groups.length) return Promise.resolve();
      hooks.onProgress({ phase: 'ai', done: g, total: groups.length });
      var group = groups[g];
      return self.claude.deepCheck(group, settings).then(function (mapped) {
        for (var i = 0; i < group.length; i++) {
          self.aiCache[self.aiKey(settings, group[i].text)] = mapped[group[i].id] || [];
        }
        g++;
        refresh('ai', self.aiCache, self.aiKey.bind(self));
        if (!cancelled()) hooks.onUpdate(entries);
        return next();
      }, function (err) {
        status.aiError = err;
        return Promise.resolve(); // one failure is enough to stop the AI pass
      });
    }
    return next();
  };

  return ltPhase().then(aiPhase).then(function () {
    if (cancelled()) status.cancelled = true;
    hooks.onProgress({ phase: 'done' });
    return status;
  });
};

// Send one chunk, retrying on rate limits and splitting on "too large".
Checker.prototype.checkChunk = function (chunk, params, hooks, attempt) {
  var self = this;
  return this.lt.check(chunk.text, params, function (waitMs) {
    hooks.onProgress({ phase: 'waiting', waitMs: waitMs });
  }).then(null, function (err) {
    if (err && err.rateLimited && attempt < 2) {
      var wait = 15000 * (attempt + 1);
      hooks.onProgress({ phase: 'waiting', waitMs: wait });
      return self.sleep(wait).then(function () {
        return self.checkChunk(chunk, params, hooks, attempt + 1);
      });
    }
    if (err && err.status === 413 && chunk.segments.length > 1) {
      var mid = Math.ceil(chunk.segments.length / 2);
      return self.checkChunk(subChunk(chunk, 0, mid), params, hooks, attempt).then(function (a) {
        return self.checkChunk(subChunk(chunk, mid, chunk.segments.length), params, hooks, attempt).then(function (b) {
          var offset = chunk.segments[mid].start;
          for (var i = 0; i < b.length; i++) b[i].offset += offset;
          return a.concat(b);
        });
      });
    }
    throw err;
  });
};

function subChunk(chunk, from, to) {
  var segs = chunk.segments.slice(from, to);
  var base = segs[0].start;
  var last = segs[segs.length - 1];
  var text = chunk.text.slice(base, last.start + last.length);
  var out = [];
  for (var i = 0; i < segs.length; i++) {
    out.push({ id: segs[i].id, start: segs[i].start - base, length: segs[i].length, paraOffset: segs[i].paraOffset });
  }
  return { text: text, segments: out };
}

function cloneTemplates(list) {
  var out = [];
  for (var i = 0; i < list.length; i++) {
    var src = list[i];
    var c = {};
    for (var k in src) if (Object.prototype.hasOwnProperty.call(src, k)) c[k] = src[k];
    c.replacements = (src.replacements || []).slice();
    out.push(c);
  }
  return out;
}

// After a fix is applied, carry the paragraph's existing LanguageTool / AI results over to
// its new text so nothing has to be re-sent. Returns the refreshed entry.
Checker.prototype.afterEdit = function (entry, start, end, replacement, newText, settings) {
  var expected = applyEdit(entry.text, start, end, replacement);
  // Only carry over real results: when an engine is switched off its list is an empty
  // placeholder, and caching that would hide the paragraph from the engine later.
  if (expected === newText && entry.checkable) {
    if (settings.useLanguageTool && entry.lt) {
      this.ltCache[this.ltKey(settings, newText)] = shiftIssues(cloneTemplates(entry.lt), start, end, replacement.length);
    }
    if (aiEnabled(settings) && entry.ai) {
      this.aiCache[this.aiKey(settings, newText)] = shiftIssues(cloneTemplates(entry.ai), start, end, replacement.length);
    }
  }
  return this.entryFor({ key: entry.key, index: entry.index, text: newText }, settings);
};

// Turn engine results into the visible issue list for one paragraph.
export function composeIssues(entry, settings, dismissed, spellingFilter) {
  var filter = spellingFilter || makeSpellingFilter(settings);
  var disabled = settings.disabledRules || {};
  function keep(list) {
    var out = [];
    if (!list) return out;
    for (var i = 0; i < list.length; i++) {
      if (disabled[list[i].ruleId]) continue;
      if (!filter(list[i])) continue;
      out.push(list[i]);
    }
    return out;
  }
  var merged = mergeIssueLists([keep(entry.lt), entry.local, keep(entry.ai)]);
  var out = [];
  for (var j = 0; j < merged.length; j++) {
    var t = merged[j];
    var sig = signature(t, entry.text);
    if (dismissed && dismissed[sig]) continue;
    var inst = instantiate(t, entry.key, entry.index);
    inst.id = t.id + '@' + entry.key;
    inst.sig = sig;
    inst.paraText = entry.text;
    out.push(inst);
  }
  return out;
}
