// WriteAssist's built-in style engine. Runs locally on each paragraph, instantly and
// offline, and adds Clarity / Engagement / Delivery suggestions to LanguageTool's
// spelling and grammar results.

import {
  WORDY, REDUNDANT, FILLERS, INTENSIFIED, CLICHES, MISUSED, INFORMAL_ALWAYS, INFORMAL_FORMAL,
  CONTRACTIONS, SENTENCE_START_CONJUNCTIONS, BE_FORMS, IRREGULAR_PARTICIPLES, ADJECTIVAL_PARTICIPLES
} from './rules-data.js';
import { createIssue } from './issues.js';
import { matchCase, escapeRegExp } from './util.js';
import { splitSentences, countWords } from './text.js';

// Writing goals tune which checks are on by default (like Grammarly's "goals").
export var GOALS = {
  general: {
    label: 'General',
    description: 'Balanced suggestions for everyday writing.',
    checks: { passive: true, longSentences: true, longSentenceWords: 30, contractions: false, informal: false, exclamation: false, conjunctionStart: false },
    picky: false
  },
  formal: {
    label: 'Formal / official',
    description: 'Letters, notes and reports for government or institutional use.',
    checks: { passive: false, longSentences: true, longSentenceWords: 35, contractions: true, informal: true, exclamation: true, conjunctionStart: true },
    picky: true
  },
  academic: {
    label: 'Academic',
    description: 'Papers, theses and study notes.',
    checks: { passive: false, longSentences: true, longSentenceWords: 40, contractions: true, informal: true, exclamation: true, conjunctionStart: true },
    picky: true
  },
  business: {
    label: 'Business',
    description: 'Emails, proposals and memos.',
    checks: { passive: true, longSentences: true, longSentenceWords: 30, contractions: false, informal: true, exclamation: false, conjunctionStart: false },
    picky: false
  },
  technical: {
    label: 'Technical report',
    description: 'Engineering reports, specifications and manuals.',
    checks: { passive: false, longSentences: true, longSentenceWords: 40, contractions: true, informal: true, exclamation: true, conjunctionStart: false },
    picky: false
  },
  casual: {
    label: 'Casual',
    description: 'Messages and informal notes.',
    checks: { passive: false, longSentences: true, longSentenceWords: 30, contractions: false, informal: false, exclamation: false, conjunctionStart: false },
    picky: false
  }
};

export var GOAL_ORDER = ['general', 'formal', 'academic', 'business', 'technical', 'casual'];

function q(s) {
  return '\u201c' + s + '\u201d';
}

function phrasePattern(phrase) {
  var words = phrase.split(/\s+/);
  var parts = [];
  for (var i = 0; i < words.length; i++) {
    parts.push(escapeRegExp(words[i]).replace(/'/g, "['\u2019]"));
  }
  var startB = /^\w/.test(phrase) ? '\\b' : '';
  var endB = /\w$/.test(phrase) ? '\\b' : '';
  return '(?:' + startB + parts.join('\\s+') + endB + ')';
}

function compileDict(dict) {
  var keys = Object.keys(dict).sort(function (a, b) {
    return b.length - a.length;
  });
  var parts = [];
  for (var i = 0; i < keys.length; i++) parts.push(phrasePattern(keys[i]));
  return { re: new RegExp(parts.join('|'), 'gi'), dict: dict };
}

function normKey(s) {
  return s.toLowerCase().replace(/\s+/g, ' ').replace(/[\u2018\u2019]/g, "'");
}

var compiled = null;
function getCompiled() {
  if (compiled) return compiled;
  var fillerDict = {};
  for (var i = 0; i < FILLERS.length; i++) fillerDict[FILLERS[i]] = [];
  var participles = IRREGULAR_PARTICIPLES.join('|');
  compiled = {
    wordy: compileDict(WORDY),
    redundant: compileDict(REDUNDANT),
    filler: compileDict(fillerDict),
    intensified: compileDict(INTENSIFIED),
    cliches: compileDict(CLICHES),
    misused: compileDict(MISUSED),
    informalAlways: compileDict(INFORMAL_ALWAYS),
    informalFormal: compileDict(INFORMAL_FORMAL),
    contractions: compileDict(CONTRACTIONS),
    passive: new RegExp(
      '\\b(?:' + BE_FORMS.join('|') + ')\\s+(?:(?:not|also|being|been|then|now|often|always|already|still|' +
        'usually|generally|recently|subsequently|properly|duly|\\w+ly)\\s+){0,2}(\\w{2,}ed|' + participles + ')\\b',
      'gi'
    ),
    adjectival: toSet(ADJECTIVAL_PARTICIPLES)
  };
  return compiled;
}

function toSet(list) {
  var set = {};
  for (var i = 0; i < list.length; i++) set[list[i].toLowerCase()] = true;
  return set;
}

// Context filters for phrases that are only informal in some constructions.
var NOT_FOLLOWED_BY = {
  'a bit': /^\s+of\b/i,
  'a couple of': /^\s+(?:hundred|thousand|lakh|crore|million)\b/i
};
var NOT_PRECEDED_BY = {
  'deal with': /\b(?:a|the|great|good|big|any|this|that)\s+$/i,
  'dealt with': /\b(?:a|the)\s+$/i,
  'check out': /\b(?:the|a)\s+$/i
};

function scanDict(text, comp, out, make) {
  var re = comp.re;
  re.lastIndex = 0;
  var m;
  while ((m = re.exec(text))) {
    if (!m[0]) {
      re.lastIndex++;
      continue;
    }
    var key = normKey(m[0]);
    var entry = comp.dict[key];
    if (!entry) continue;
    var after = text.slice(m.index + m[0].length);
    var before = text.slice(0, m.index);
    if (NOT_FOLLOWED_BY[key] && NOT_FOLLOWED_BY[key].test(after)) continue;
    if (NOT_PRECEDED_BY[key] && NOT_PRECEDED_BY[key].test(before)) continue;
    var issue = make(m, key, entry, before, after);
    if (issue) out.push(issue);
  }
}

function caseReps(original, reps) {
  var out = [];
  for (var i = 0; i < reps.length; i++) out.push(matchCase(original, reps[i]));
  return out;
}

function phraseIssue(type, ruleFamily, messageFn) {
  return function (m, key, entry) {
    var reps = entry.replacements || entry;
    return createIssue({
      source: 'local',
      ruleId: 'WA_' + ruleFamily + ':' + key,
      type: entry.type || type,
      message: entry.message || messageFn(m[0], reps),
      offset: m.index,
      length: m[0].length,
      original: m[0],
      replacements: caseReps(m[0], reps)
    });
  };
}

function isSentenceStart(before) {
  return /^\s*$/.test(before) || /[.!?:;]["'\u201d\u2019)]?\s+$/.test(before);
}

// Builds a removal suggestion for filler words, keeping punctuation and capitals correct.
function removalIssue(text, start, end, ruleId, type, message, label) {
  var e = end;
  var trailingComma = /^\s*,/.exec(text.slice(e));
  if (trailingComma) e += trailingComma[0].length;
  var before = text.slice(0, start);
  var spanStart = start;
  var spanEnd;
  var replacement;
  if (isSentenceStart(before)) {
    var rest = text.slice(e);
    var ws = /^\s*/.exec(rest)[0];
    var nextChar = rest.charAt(ws.length);
    if (!nextChar || !/[A-Za-z]/.test(nextChar)) return null;
    spanEnd = e + ws.length + 1;
    replacement = nextChar.toUpperCase();
  } else if (trailingComma && /,\s*$/.test(before)) {
    spanStart = start - /,\s*$/.exec(before)[0].length;
    spanEnd = e;
    replacement = '';
  } else {
    var ws2 = /^\s*/.exec(text.slice(e))[0];
    spanEnd = e + ws2.length;
    if (!ws2 && !trailingComma) {
      // phrase at the very end of a sentence: drop the space in front instead
      var lead = /\s+$/.exec(before);
      if (!lead) return null;
      spanStart = start - lead[0].length;
    }
    replacement = '';
  }
  var issue = createIssue({
    source: 'local',
    ruleId: ruleId,
    type: type,
    message: message,
    offset: spanStart,
    length: spanEnd - spanStart,
    original: text.slice(spanStart, spanEnd),
    replacements: [replacement]
  });
  issue.labels = [label];
  issue.display = text.slice(start, end);
  return issue;
}

export function effectiveChecks(settings) {
  var goal = GOALS[settings.goal] || GOALS.general;
  var c = settings.checks || {};
  function pick(name, fallback) {
    return typeof c[name] === 'boolean' || typeof c[name] === 'number' ? c[name] : fallback;
  }
  return {
    wordy: pick('wordy', true),
    redundancy: pick('redundancy', true),
    fillers: pick('fillers', true),
    weakWords: pick('weakWords', true),
    cliches: pick('cliches', true),
    misused: pick('misused', true),
    informal: pick('informal', goal.checks.informal),
    contractions: pick('contractions', goal.checks.contractions),
    exclamation: pick('exclamation', goal.checks.exclamation),
    conjunctionStart: pick('conjunctionStart', goal.checks.conjunctionStart),
    passive: pick('passive', goal.checks.passive),
    longSentences: pick('longSentences', goal.checks.longSentences),
    longSentenceWords: pick('longSentenceWords', goal.checks.longSentenceWords),
    spacing: pick('spacing', true),
    repeatedWords: pick('repeatedWords', true),
    casual: settings.goal === 'casual'
  };
}

// Run all enabled local checks on one paragraph. Returns issue templates (no paragraph key).
export function runLocalRules(text, settings, disabledRules) {
  var out = [];
  if (!text || !/[A-Za-z]/.test(text)) return out;
  var ch = effectiveChecks(settings);
  var comp = getCompiled();

  if (ch.misused) {
    scanDict(text, comp.misused, out, phraseIssue('grammar', 'MISUSED', function (orig, reps) {
      return 'Use ' + q(reps[0]) + ' instead of ' + q(orig) + '.';
    }));
  }
  if (ch.wordy) {
    scanDict(text, comp.wordy, out, phraseIssue('wordy', 'WORDY', function (orig, reps) {
      return q(orig) + ' is wordy. ' + q(reps[0]) + ' says the same thing more directly.';
    }));
  }
  if (ch.redundancy) {
    scanDict(text, comp.redundant, out, phraseIssue('redundancy', 'REDUNDANT', function (orig, reps) {
      return q(orig) + ' repeats itself. ' + q(reps[0]) + ' carries the meaning on its own.';
    }));
  }
  if (ch.fillers) {
    scanDict(text, comp.filler, out, function (m, key) {
      var single = key.indexOf(' ') === -1;
      return removalIssue(
        text, m.index, m.index + m[0].length, 'WA_FILLER:' + key, single ? 'weak-word' : 'wordy',
        single
          ? q(m[0]) + ' rarely adds meaning. Removing it makes the sentence more direct.'
          : 'This phrase adds words without adding meaning. Consider removing it.',
        single ? 'Remove ' + q(m[0]) : 'Remove the phrase'
      );
    });
  }
  if (ch.weakWords) {
    scanDict(text, comp.intensified, out, phraseIssue('weak-word', 'INTENSIFIER', function (orig) {
      return q(orig) + ' relies on an intensifier. One precise word is stronger.';
    }));
  }
  if (ch.cliches) {
    scanDict(text, comp.cliches, out, phraseIssue('cliche', 'CLICHE', function (orig, reps) {
      return reps.length
        ? q(orig) + ' is an overused expression. Plainer wording reads as more original.'
        : q(orig) + ' is an overused expression. Consider saying what you mean directly.';
    }));
  }
  if (!ch.casual) {
    scanDict(text, comp.informalAlways, out, phraseIssue('formality', 'INFORMAL', function (orig, reps) {
      return q(orig) + ' is informal. Use ' + q(reps[0]) + ' in written English.';
    }));
  }
  if (ch.informal) {
    scanDict(text, comp.informalFormal, out, phraseIssue('formality', 'INFORMAL_FORMAL', function (orig, reps) {
      return q(orig) + ' sounds conversational for this goal. Consider ' + q(reps[0]) + '.';
    }));
  }
  if (ch.contractions) {
    scanDict(text, comp.contractions, out, phraseIssue('formality', 'CONTRACTION', function (orig, reps) {
      return 'Contractions can feel informal. Spell out ' + q(orig) + ' as ' + q(reps[0]) + ' for this goal.';
    }));
  }
  if (ch.spacing) spacingRules(text, out, ch);
  if (ch.repeatedWords) repeatedWordRule(text, out);
  if (ch.exclamation) exclamationRule(text, out);

  var sentences = null;
  if (ch.conjunctionStart || ch.longSentences || ch.passive) sentences = splitSentences(text);
  if (ch.conjunctionStart) conjunctionStartRule(text, sentences, out);
  if (ch.longSentences) longSentenceRule(sentences, ch.longSentenceWords, out);
  if (ch.passive) passiveRule(text, sentences, comp, out);

  if (disabledRules) {
    var filtered = [];
    for (var i = 0; i < out.length; i++) {
      var fam = out[i].ruleId.split(':')[0];
      if (!disabledRules[out[i].ruleId] && !disabledRules[fam]) filtered.push(out[i]);
    }
    out = filtered;
  }
  return out;
}

function spacingRules(text, out, ch) {
  var m;
  var multi = /([^\s])( {2,})(?=[^\s])/g;
  while ((m = multi.exec(text))) {
    var issue = createIssue({
      source: 'local', ruleId: 'WA_SPACES', type: 'punctuation',
      message: 'There are extra spaces between these words.',
      offset: m.index + 1, length: m[2].length, original: m[2], replacements: [' ']
    });
    issue.labels = ['Use one space'];
    issue.display = text.slice(Math.max(0, m.index - 6), m.index + 1 + m[2].length + 6);
    out.push(issue);
  }
  var before = /([^\s,;:.!?])( +)([,;:.!?])(?![.\d])/g;
  while ((m = before.exec(text))) {
    var start = m.index + 1;
    var iss = createIssue({
      source: 'local', ruleId: 'WA_SPACE_BEFORE_PUNCT', type: 'punctuation',
      message: 'Remove the space before ' + q(m[3]) + '.',
      offset: start, length: m[2].length + 1, original: m[2] + m[3], replacements: [m[3]]
    });
    iss.labels = ['Remove the space'];
    out.push(iss);
    before.lastIndex = start + m[2].length + 1;
  }
  var after = /([a-z]{2,}),(?=[A-Za-z]{2,})/g;
  while ((m = after.exec(text))) {
    var off = m.index + m[1].length;
    var is2 = createIssue({
      source: 'local', ruleId: 'WA_SPACE_AFTER_COMMA', type: 'punctuation',
      message: 'Add a space after the comma.',
      offset: off, length: 1, original: ',', replacements: [', ']
    });
    is2.labels = ['Add a space'];
    out.push(is2);
  }
  var repeated = ch.casual ? /([,;:])\1+/g : /([,;:!?])\1+/g;
  while ((m = repeated.exec(text))) {
    out.push(createIssue({
      source: 'local', ruleId: 'WA_REPEATED_PUNCT', type: 'punctuation',
      message: 'Use a single ' + q(m[1]) + '.',
      offset: m.index, length: m[0].length, original: m[0], replacements: [m[1]]
    }));
  }
}

var REPEAT_OK = { had: true, that: true, is: false };
function repeatedWordRule(text, out) {
  var re = /\b([A-Za-z]+)(\s+)\1\b/gi;
  var m;
  while ((m = re.exec(text))) {
    var w = m[1].toLowerCase();
    if (REPEAT_OK[w]) continue;
    out.push(createIssue({
      source: 'local', ruleId: 'WA_REPEATED_WORD', type: 'grammar', title: 'Repeated word',
      message: 'The word ' + q(m[1]) + ' appears twice in a row.',
      offset: m.index, length: m[0].length, original: m[0], replacements: [m[1]]
    }));
  }
}

function exclamationRule(text, out) {
  var re = /([A-Za-z0-9)\]"'\u201d\u2019])!(?![!=])/g;
  var m;
  while ((m = re.exec(text))) {
    var off = m.index + m[1].length;
    out.push(createIssue({
      source: 'local', ruleId: 'WA_EXCLAMATION', type: 'tone',
      message: 'Exclamation marks can sound emotional in formal writing. A full stop keeps the tone measured.',
      offset: off, length: 1, original: '!', replacements: ['.']
    }));
  }
}

function conjunctionStartRule(text, sentences, out) {
  for (var i = 0; i < sentences.length; i++) {
    var s = sentences[i];
    var m = /^(And|But|So)\b(?!\s+(?:far|much|many|long|called|that|on|forth)\b)(?!-)/.exec(s.text);
    if (!m) continue;
    var reps = SENTENCE_START_CONJUNCTIONS[m[1].toLowerCase()];
    out.push(createIssue({
      source: 'local', ruleId: 'WA_CONJ_START', type: 'tone',
      message: 'Starting a sentence with ' + q(m[1]) + ' can sound conversational in formal writing.',
      offset: s.start, length: m[1].length, original: m[1], replacements: reps
    }));
  }
}

function longSentenceRule(sentences, limit, out) {
  for (var i = 0; i < sentences.length; i++) {
    var s = sentences[i];
    var n = countWords(s.text);
    if (n > limit) {
      out.push(createIssue({
        source: 'local', ruleId: 'WA_LONG_SENTENCE', type: 'long-sentence', sentenceLevel: true,
        message: 'This sentence has ' + n + ' words. Readers follow sentences of under ' + limit +
          ' words more easily; consider splitting it in two.',
        offset: s.start, length: s.end - s.start, original: s.text, replacements: []
      }));
    }
  }
}

function passiveRule(text, sentences, comp, out) {
  var re = comp.passive;
  for (var i = 0; i < sentences.length; i++) {
    var s = sentences[i];
    re.lastIndex = 0;
    var m;
    while ((m = re.exec(s.text))) {
      var participle = m[1].toLowerCase();
      if (comp.adjectival[participle]) continue;
      if (/eed$/.test(participle)) continue;
      if (/^(?:hundred|sacred|naked|wicked|rugged|crooked|ragged|kindred|hatred|shred|sled|bed|red|wed)$/.test(participle)) continue;
      out.push(createIssue({
        source: 'local', ruleId: 'WA_PASSIVE', type: 'passive',
        message: 'Passive voice can hide who is acting. An active sentence (\u201cThe committee approved the plan\u201d rather than \u201cThe plan was approved\u201d) is usually clearer.',
        offset: s.start + m.index, length: m[0].length, original: m[0], replacements: []
      }));
      break; // one note per sentence is enough
    }
  }
}
